-- FinanceTracker: complete database setup for a NEW Supabase project.
-- Generated by scripts/build_supabase_setup.py from supabase/migrations/. Do not edit by hand.
-- Run once in SQL Editor on an empty project. Included, in order:
--   20261114000000_init.sql
--   20261115000000_ocr_usage.sql
--   20261116000000_telegram.sql
--   20261117000000_ledger_closing.sql
--   20261118000000_plans.sql
--   20261119000000_plan_ledger.sql
--   20261120000000_plan_sale_and_month_end.sql
--   20261121000000_scheduled_jobs.sql
--   20261122000000_loans.sql

-- ====================================================================
-- 20261114000000_init.sql
-- ====================================================================

-- FinanceTracker V2, phase 1: schema + row-level security.
--
-- Apply with `supabase db push`, or paste the whole file into the Supabase
-- SQL Editor and run it once.
--
-- Model: every row belongs to a household; a user may touch a row only if
-- they are a member of that household. Types and column names mirror the V1
-- Google Sheet (code.gs) so the import and the front-end port stay simple.

-- ---------------------------------------------------------------
-- Private helpers (schema is not exposed through the Data API)
-- ---------------------------------------------------------------
create schema if not exists private;

-- ---------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------
create table public.households (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (length(trim(name)) > 0),
  data_source text not null default 'supabase' check (data_source in ('supabase', 'sheets')),
  created_by  uuid references auth.users (id) on delete set null default auth.uid(),
  created_at  timestamptz not null default now()
);

create table public.members (
  household_id uuid not null references public.households (id) on delete cascade,
  user_id      uuid not null references auth.users (id) on delete cascade,
  role         text not null default 'member' check (role in ('owner', 'member')),
  created_at   timestamptz not null default now(),
  primary key (household_id, user_id)
);
create index members_user_idx on public.members (user_id);

-- User-defined accounts (replaces the hard-coded ACCOUNTS list).
create table public.accounts (
  id              uuid primary key default gen_random_uuid(),
  household_id    uuid not null references public.households (id) on delete cascade,
  name            text not null check (length(trim(name)) > 0),
  opening_balance numeric(18, 2) not null default 0,
  archived        boolean not null default false,
  sort_order      integer not null default 0,
  created_at      timestamptz not null default now()
);
create unique index accounts_name_uq on public.accounts (household_id, lower(name));

create table public.categories (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  name         text not null check (length(trim(name)) > 0),
  created_at   timestamptz not null default now()
);
create unique index categories_name_uq on public.categories (household_id, lower(name));

create table public.transactions (
  id             uuid primary key default gen_random_uuid(),
  household_id   uuid not null references public.households (id) on delete cascade,
  date           date not null default ((now() at time zone 'Asia/Jakarta')::date),
  type           text not null check (type in ('income', 'expense', 'invest', 'transfer-out', 'transfer-in')),
  category_id    uuid references public.categories (id) on delete set null,
  description    text not null default '',
  amount         numeric(18, 2) not null check (amount >= 0),
  source         text not null default 'web',
  account_id     uuid references public.accounts (id) on delete set null,  -- null = unassigned
  transfer_group uuid,          -- shared by the two legs of one transfer
  legacy_id      text,          -- V1 sheet id (TXN-..., TRF-...); makes the import re-runnable
  created_by     uuid references auth.users (id) on delete set null default auth.uid(),
  created_at     timestamptz not null default now(),
  unique (household_id, legacy_id)
);
create index transactions_household_date_idx on public.transactions (household_id, date desc);
create index transactions_account_idx on public.transactions (account_id);

create table public.holdings (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  asset_type   text not null check (asset_type in ('gold', 'stock')),
  ticker       text not null default '',   -- gold is 'LM', brand goes in name
  name         text not null default '',
  quantity     numeric(18, 6) not null check (quantity > 0),  -- grams or shares
  buy_price    numeric(18, 2) not null check (buy_price >= 0), -- per gram / per share
  buy_date     date,
  legacy_id    text,
  created_at   timestamptz not null default now(),
  unique (household_id, legacy_id)
);
create index holdings_household_idx on public.holdings (household_id);

-- Realized P&L, one row per sale (the V1 "Realized" tab).
create table public.sales (
  id            uuid primary key default gen_random_uuid(),
  household_id  uuid not null references public.households (id) on delete cascade,
  date          date not null default ((now() at time zone 'Asia/Jakarta')::date),
  asset_type    text not null,
  ticker        text not null default '',
  name          text not null default '',
  quantity      numeric(18, 6) not null,
  avg_buy_price numeric(18, 2) not null,
  sell_price    numeric(18, 2) not null,
  proceeds      numeric(18, 2) not null,
  cost_basis    numeric(18, 2) not null,
  realized_pl   numeric(18, 2) not null,
  account_id    uuid references public.accounts (id) on delete set null,
  legacy_id     text,
  created_at    timestamptz not null default now(),
  unique (household_id, legacy_id)
);
create index sales_household_idx on public.sales (household_id, date desc);

-- Receipt photos (used from phase 3; the storage bucket is created then).
create table public.receipts (
  id             uuid primary key default gen_random_uuid(),
  household_id   uuid not null references public.households (id) on delete cascade,
  transaction_id uuid references public.transactions (id) on delete cascade,
  storage_path   text not null,
  created_at     timestamptz not null default now()
);

-- Telegram chat linked to a member (used from phase 4).
create table public.telegram_links (
  user_id          uuid primary key references auth.users (id) on delete cascade,
  household_id     uuid not null references public.households (id) on delete cascade,
  telegram_user_id bigint not null unique,
  linked_at        timestamptz not null default now()
);

-- ---------------------------------------------------------------
-- Membership checks. SECURITY DEFINER so policies on `members` do not
-- recurse into themselves; search_path is pinned for safety.
-- ---------------------------------------------------------------
create function private.is_member(hid uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.members m
    where m.household_id = hid and m.user_id = (select auth.uid())
  );
$$;

create function private.is_owner(hid uuid)
returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.members m
    where m.household_id = hid and m.user_id = (select auth.uid()) and m.role = 'owner'
  );
$$;

grant usage on schema private to authenticated;
revoke all on function private.is_member(uuid) from public;
revoke all on function private.is_owner(uuid) from public;
grant execute on function private.is_member(uuid) to authenticated;
grant execute on function private.is_owner(uuid) to authenticated;

-- ---------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------
alter table public.households     enable row level security;
alter table public.members        enable row level security;
alter table public.accounts       enable row level security;
alter table public.categories     enable row level security;
alter table public.transactions   enable row level security;
alter table public.holdings       enable row level security;
alter table public.sales          enable row level security;
alter table public.receipts       enable row level security;
alter table public.telegram_links enable row level security;

-- Households: members read; owners rename / switch source / delete.
-- Creation goes through create_household() below.
create policy households_select on public.households
  for select to authenticated using (private.is_member(id));
create policy households_update on public.households
  for update to authenticated using (private.is_owner(id)) with check (private.is_owner(id));
create policy households_delete on public.households
  for delete to authenticated using (private.is_owner(id));

-- Members: everyone in the household sees the list; owners remove people;
-- anyone may leave. Adding goes through add_member_by_email() below.
create policy members_select on public.members
  for select to authenticated using (private.is_member(household_id));
create policy members_delete on public.members
  for delete to authenticated
  using (private.is_owner(household_id) or user_id = (select auth.uid()));

-- Household data: full access for members, nothing for anyone else.
create policy accounts_all on public.accounts
  for all to authenticated
  using (private.is_member(household_id)) with check (private.is_member(household_id));
create policy categories_all on public.categories
  for all to authenticated
  using (private.is_member(household_id)) with check (private.is_member(household_id));
create policy transactions_all on public.transactions
  for all to authenticated
  using (private.is_member(household_id)) with check (private.is_member(household_id));
create policy holdings_all on public.holdings
  for all to authenticated
  using (private.is_member(household_id)) with check (private.is_member(household_id));
create policy sales_all on public.sales
  for all to authenticated
  using (private.is_member(household_id)) with check (private.is_member(household_id));
create policy receipts_all on public.receipts
  for all to authenticated
  using (private.is_member(household_id)) with check (private.is_member(household_id));

-- Telegram link: each user manages only their own.
create policy telegram_links_own on public.telegram_links
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()) and private.is_member(household_id));

-- Logged-out visitors get nothing, even if RLS were ever switched off.
revoke all on all tables in schema public from anon;
grant select, insert, update, delete on all tables in schema public to authenticated;
-- Server-side jobs (import script, edge functions) use the secret key.
grant all on all tables in schema public to service_role;

-- ---------------------------------------------------------------
-- Per-account balance (V1 getAccountBalances_). Runs with the caller's
-- rights, so RLS still applies.
-- ---------------------------------------------------------------
create view public.account_balances
with (security_invoker = true) as
select
  a.id as account_id,
  a.household_id,
  a.name,
  a.archived,
  a.sort_order,
  a.opening_balance + coalesce(sum(
    case when t.type in ('income', 'transfer-in') then t.amount else -t.amount end
  ), 0) as balance
from public.accounts a
left join public.transactions t on t.account_id = a.id
group by a.id;

revoke all on public.account_balances from anon;
grant select on public.account_balances to authenticated, service_role;

-- ---------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------

-- First-run onboarding: create a household, make the caller its owner,
-- and add the accounts they typed in.
create function public.create_household(p_name text, p_accounts text[] default '{}')
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_uid uuid := (select auth.uid());
  v_id  uuid;
  v_acc text;
  v_pos integer := 0;
begin
  if v_uid is null then
    raise exception 'Not signed in';
  end if;

  insert into public.households (name, created_by)
  values (trim(p_name), v_uid) returning id into v_id;

  insert into public.members (household_id, user_id, role)
  values (v_id, v_uid, 'owner');

  foreach v_acc in array coalesce(p_accounts, '{}') loop
    if length(trim(v_acc)) > 0 then
      insert into public.accounts (household_id, name, sort_order)
      values (v_id, trim(v_acc), v_pos);
      v_pos := v_pos + 1;
    end if;
  end loop;

  return v_id;
end;
$$;

-- Owner adds an existing user (invited from the Supabase dashboard) by email.
create function public.add_member_by_email(p_household uuid, p_email text)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_user uuid;
begin
  if not private.is_owner(p_household) then
    raise exception 'Only the household owner can add members';
  end if;

  select u.id into v_user from auth.users u where lower(u.email) = lower(trim(p_email));
  if v_user is null then
    raise exception 'No user with that email. Invite them first.';
  end if;

  insert into public.members (household_id, user_id, role)
  values (p_household, v_user, 'member')
  on conflict do nothing;
end;
$$;

-- Transfer = two linked rows, written atomically (V1 addTransfer_).
-- Runs as the caller, so RLS decides whether it is allowed.
create function public.add_transfer(
  p_household uuid,
  p_from      uuid,
  p_to        uuid,
  p_amount    numeric,
  p_date      date default null,
  p_note      text default '',
  p_source    text default 'web'
)
returns uuid
language plpgsql security invoker set search_path = ''
as $$
declare
  v_group     uuid := gen_random_uuid();
  v_date      date := coalesce(p_date, (now() at time zone 'Asia/Jakarta')::date);
  v_from_name text;
  v_to_name   text;
  v_cat       uuid;
  v_suffix    text := case when coalesce(p_note, '') <> '' then ' - ' || p_note else '' end;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be positive';
  end if;
  if p_from = p_to then
    raise exception 'Choose two different accounts';
  end if;

  select name into v_from_name from public.accounts where id = p_from and household_id = p_household;
  select name into v_to_name   from public.accounts where id = p_to   and household_id = p_household;
  if v_from_name is null or v_to_name is null then
    raise exception 'Account not found in this household';
  end if;

  select id into v_cat from public.categories
  where household_id = p_household and lower(name) = 'transfer';
  if v_cat is null then
    insert into public.categories (household_id, name)
    values (p_household, 'Transfer') returning id into v_cat;
  end if;

  insert into public.transactions
    (household_id, date, type, category_id, description, amount, source, account_id, transfer_group)
  values
    (p_household, v_date, 'transfer-out', v_cat, 'To ' || v_to_name || v_suffix,
     p_amount, p_source, p_from, v_group),
    (p_household, v_date, 'transfer-in', v_cat, 'From ' || v_from_name || v_suffix,
     p_amount, p_source, p_to, v_group);

  return v_group;
end;
$$;

-- Sell a holding (V1 sellHolding_): draw lots down first-in first-out,
-- log the proceeds as income, and record realized P&L. All or nothing.
-- Match by p_holding (one lot) or by p_ticker and/or p_name.
create function public.sell_holding(
  p_household  uuid,
  p_quantity   numeric,
  p_sell_price numeric,
  p_account    uuid default null,
  p_holding    uuid default null,
  p_ticker     text default null,
  p_name       text default null,
  p_date       date default null,
  p_source     text default 'web'
)
returns public.sales
language plpgsql security invoker set search_path = ''
as $$
declare
  v_date      date := coalesce(p_date, (now() at time zone 'Asia/Jakarta')::date);
  v_ticker    text := upper(trim(coalesce(p_ticker, '')));
  v_name      text := lower(trim(coalesce(p_name, '')));
  v_remaining numeric := p_quantity;
  v_available numeric := 0;
  v_cost      numeric := 0;
  v_take      numeric;
  v_type      text;
  v_lot_tick  text;
  v_lot_name  text;
  v_label     text;
  v_proceeds  numeric;
  v_cat       uuid;
  v_lot       record;
  v_sale      public.sales;
begin
  if p_quantity is null or p_quantity <= 0 or p_sell_price is null or p_sell_price <= 0 then
    raise exception 'Quantity and sell price must be positive';
  end if;
  if p_holding is null and v_ticker = '' and v_name = '' then
    raise exception 'Say which holding to sell';
  end if;

  for v_lot in
    select h.* from public.holdings h
    where h.household_id = p_household
      and (
        (p_holding is not null and h.id = p_holding)
        or (p_holding is null
            and (v_ticker = '' or upper(trim(h.ticker)) = v_ticker)
            and (v_name   = '' or lower(trim(h.name))   = v_name))
      )
    order by h.created_at, h.id
    for update
  loop
    v_available := v_available + v_lot.quantity;
    v_type := v_lot.asset_type; v_lot_tick := v_lot.ticker; v_lot_name := v_lot.name;

    if v_remaining > 0 then
      v_take := least(v_lot.quantity, v_remaining);
      v_cost := v_cost + v_take * v_lot.buy_price;
      v_remaining := v_remaining - v_take;
      if v_lot.quantity - v_take <= 0 then
        delete from public.holdings where id = v_lot.id;
      else
        update public.holdings set quantity = quantity - v_take where id = v_lot.id;
      end if;
    end if;
  end loop;

  if v_type is null then
    raise exception 'No matching holding found';
  end if;
  if v_remaining > 0 then
    -- raising rolls back the draw-down above
    raise exception 'Selling % but only % held', p_quantity, v_available;
  end if;

  v_proceeds := p_quantity * p_sell_price;
  v_label := coalesce(nullif(v_lot_name, ''), nullif(v_lot_tick, ''), v_type);

  select id into v_cat from public.categories
  where household_id = p_household and lower(name) = 'asset sale';
  if v_cat is null then
    insert into public.categories (household_id, name)
    values (p_household, 'Asset Sale') returning id into v_cat;
  end if;

  insert into public.transactions
    (household_id, date, type, category_id, description, amount, source, account_id)
  values
    (p_household, v_date, 'income', v_cat,
     'Sold ' || p_quantity || ' ' || v_label || ' @ ' || p_sell_price ||
       case when v_proceeds - v_cost >= 0 then ' (gain)' else ' (loss)' end,
     v_proceeds, p_source, p_account);

  insert into public.sales
    (household_id, date, asset_type, ticker, name, quantity, avg_buy_price,
     sell_price, proceeds, cost_basis, realized_pl, account_id)
  values
    (p_household, v_date, v_type, v_lot_tick, v_lot_name, p_quantity, v_cost / p_quantity,
     p_sell_price, v_proceeds, v_cost, v_proceeds - v_cost, p_account)
  returning * into v_sale;

  return v_sale;
end;
$$;

-- RPCs are for signed-in users only.
revoke all on function public.create_household(text, text[]) from public, anon;
revoke all on function public.add_member_by_email(uuid, text) from public, anon;
revoke all on function public.add_transfer(uuid, uuid, uuid, numeric, date, text, text) from public, anon;
revoke all on function public.sell_holding(uuid, numeric, numeric, uuid, uuid, text, text, date, text) from public, anon;
grant execute on function public.create_household(text, text[]) to authenticated;
grant execute on function public.add_member_by_email(uuid, text) to authenticated;
grant execute on function public.add_transfer(uuid, uuid, uuid, numeric, date, text, text) to authenticated;
grant execute on function public.sell_holding(uuid, numeric, numeric, uuid, uuid, text, text, date, text) to authenticated;

-- ====================================================================
-- 20261115000000_ocr_usage.sql
-- ====================================================================

-- Phase 3: daily scan limit for the "ocr" Edge Function.
-- Each scan calls use_ocr_scan(), which counts it against the caller and
-- refuses once the day's limit is reached. Run this once in the SQL Editor.

create table public.ocr_usage (
  user_id uuid not null references auth.users (id) on delete cascade,
  day     date not null,
  scans   int  not null default 0,
  primary key (user_id, day)
);

alter table public.ocr_usage enable row level security;

-- Users may read their own counter; only use_ocr_scan() writes it.
create policy ocr_usage_own on public.ocr_usage
  for select to authenticated using (user_id = (select auth.uid()));

revoke all on public.ocr_usage from anon, authenticated;
grant select on public.ocr_usage to authenticated;
grant all on public.ocr_usage to service_role;

-- Counts one scan for the signed-in user and returns how many are left today.
-- Raises when the user is not in any household or has used up the day.
create function public.use_ocr_scan()
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user  uuid := (select auth.uid());
  v_day   date := (now() at time zone 'Asia/Jakarta')::date;
  v_limit constant int := 30;
  v_scans int;
begin
  if v_user is null then
    raise exception 'Not signed in';
  end if;
  if not exists (select 1 from public.members m where m.user_id = v_user) then
    raise exception 'Not a household member';
  end if;

  insert into public.ocr_usage as u (user_id, day, scans)
  values (v_user, v_day, 1)
  on conflict (user_id, day) do update set scans = u.scans + 1
    where u.scans < v_limit
  returning u.scans into v_scans;

  if v_scans is null then
    raise exception 'Daily scan limit reached (% a day). Try again tomorrow.', v_limit;
  end if;
  return v_limit - v_scans;
end;
$$;

revoke all on function public.use_ocr_scan() from public, anon;
grant execute on function public.use_ocr_scan() to authenticated;

-- ====================================================================
-- 20261116000000_telegram.sql
-- ====================================================================

-- Phase 4: the Telegram bot as a Supabase Edge Function ("telegram").
-- Adds one-time link codes (app -> bot), per-chat conversation state, and the
-- pieces the function needs when it acts with the service role.
-- Run this once in the SQL Editor.

-- One-time codes: created in the app, typed into the bot as "/link CODE".
create table public.telegram_link_codes (
  code         text primary key,
  user_id      uuid not null references auth.users (id) on delete cascade,
  household_id uuid not null references public.households (id) on delete cascade,
  expires_at   timestamptz not null
);

-- What the bot is in the middle of with each Telegram user (pending entry,
-- rows waiting for review, "next photo is a payslip", ...).
create table public.telegram_state (
  telegram_user_id bigint primary key,
  state            jsonb not null default '{}'::jsonb,
  updated_at       timestamptz not null default now()
);

-- Both tables are for the Edge Function only: RLS on, no policies, no grants
-- to signed-in users. The service role bypasses RLS.
alter table public.telegram_link_codes enable row level security;
alter table public.telegram_state      enable row level security;
revoke all on public.telegram_link_codes, public.telegram_state from anon, authenticated;
grant all on public.telegram_link_codes, public.telegram_state to service_role;

-- Called from the app (Settings -> Link Telegram). Returns a code that is
-- valid for 10 minutes; any earlier code of the same user is dropped.
create function public.create_telegram_link_code(p_household uuid)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_code text;
begin
  if v_user is null or not private.is_member(p_household) then
    raise exception 'Not a member of this household';
  end if;
  delete from public.telegram_link_codes
  where user_id = v_user or expires_at < now();
  v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  insert into public.telegram_link_codes (code, user_id, household_id, expires_at)
  values (v_code, v_user, p_household, now() + interval '10 minutes');
  return v_code;
end;
$$;

revoke all on function public.create_telegram_link_code(uuid) from public, anon;
grant execute on function public.create_telegram_link_code(uuid) to authenticated;

-- Same daily scan limit as use_ocr_scan(), for the bot: the Edge Function
-- passes the linked user because it has no user session of its own.
create function public.use_ocr_scan_for(p_user uuid)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_day   date := (now() at time zone 'Asia/Jakarta')::date;
  v_limit constant int := 30;
  v_scans int;
begin
  insert into public.ocr_usage as u (user_id, day, scans)
  values (p_user, v_day, 1)
  on conflict (user_id, day) do update set scans = u.scans + 1
    where u.scans < v_limit
  returning u.scans into v_scans;

  if v_scans is null then
    raise exception 'Daily scan limit reached (% a day). Try again tomorrow.', v_limit;
  end if;
  return v_limit - v_scans;
end;
$$;

revoke all on function public.use_ocr_scan_for(uuid) from public, anon, authenticated;
grant execute on function public.use_ocr_scan_for(uuid) to service_role;

-- The bot records transfers and sales through the same RPCs as the app.
grant execute on function public.add_transfer(uuid, uuid, uuid, numeric, date, text, text) to service_role;
grant execute on function public.sell_holding(uuid, numeric, numeric, uuid, uuid, text, text, date, text) to service_role;

-- ====================================================================
-- 20261117000000_ledger_closing.sql
-- ====================================================================

-- V2.4: monthly ledger closing.
-- A month is closed only by an owner, by hand (close_period). Closing stores a
-- snapshot of the month's figures and locks every transaction and sale dated in
-- or before that month. reopen_period unlocks the latest closed month again and
-- records why. The first close may be any finished month (everything before it
-- becomes the opening balance); after that, months close one after another.
-- Run this once in the SQL Editor (or with `supabase db push`).

-- ---------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------
create table public.ledger_closings (
  id              uuid primary key default gen_random_uuid(),
  household_id    uuid not null references public.households (id) on delete cascade,
  month           date not null check (extract(day from month) = 1),
  version         int  not null default 1,
  status          text not null default 'closed' check (status in ('closed', 'superseded')),
  opening         numeric(18, 2) not null,
  income          numeric(18, 2) not null,
  expense         numeric(18, 2) not null,
  invest          numeric(18, 2) not null,
  transfer_in     numeric(18, 2) not null,
  transfer_out    numeric(18, 2) not null,
  closing         numeric(18, 2) not null,
  savings_rate    numeric(7, 2),
  realized_pl     numeric(18, 2) not null default 0,
  portfolio_value numeric(18, 2),
  unrealized_pl   numeric(18, 2),
  by_category     jsonb not null default '[]',
  checklist       jsonb not null default '{}',
  note            text not null default '',
  closed_by       uuid references auth.users (id) on delete set null default auth.uid(),
  closed_at       timestamptz not null default now(),
  unique (household_id, month, version)
);
-- at most one live snapshot per month; reopened ones become 'superseded'
create unique index ledger_closings_one_closed on public.ledger_closings (household_id, month)
  where status = 'closed';

create table public.ledger_closing_accounts (
  id              uuid primary key default gen_random_uuid(),
  closing_id      uuid not null references public.ledger_closings (id) on delete cascade,
  household_id    uuid not null references public.households (id) on delete cascade,
  account_id      uuid references public.accounts (id) on delete set null, -- null = unassigned entries
  account_name    text not null,
  sort_order      int not null default 0,
  opening         numeric(18, 2) not null,
  income          numeric(18, 2) not null,
  expense         numeric(18, 2) not null,
  invest          numeric(18, 2) not null,
  transfer_in     numeric(18, 2) not null,
  transfer_out    numeric(18, 2) not null,
  closing         numeric(18, 2) not null,
  bank_balance    numeric(18, 2),
  difference      numeric(18, 2),
  difference_note text not null default ''
);
create index ledger_closing_accounts_closing_idx on public.ledger_closing_accounts (closing_id);

create table public.ledger_closing_events (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  month        date not null,
  version      int  not null,
  action       text not null check (action in ('close', 'reopen')),
  reason       text not null default '',
  user_id      uuid references auth.users (id) on delete set null default auth.uid(),
  at           timestamptz not null default now()
);
create index ledger_closing_events_household_idx on public.ledger_closing_events (household_id, month);

-- Members read; only the RPCs below write.
alter table public.ledger_closings         enable row level security;
alter table public.ledger_closing_accounts enable row level security;
alter table public.ledger_closing_events   enable row level security;

create policy ledger_closings_select on public.ledger_closings
  for select to authenticated using (private.is_member(household_id));
create policy ledger_closing_accounts_select on public.ledger_closing_accounts
  for select to authenticated using (private.is_member(household_id));
create policy ledger_closing_events_select on public.ledger_closing_events
  for select to authenticated using (private.is_member(household_id));

revoke all on public.ledger_closings, public.ledger_closing_accounts, public.ledger_closing_events
  from anon, authenticated;
grant select on public.ledger_closings, public.ledger_closing_accounts, public.ledger_closing_events
  to authenticated;
grant all on public.ledger_closings, public.ledger_closing_accounts, public.ledger_closing_events
  to service_role;

-- ---------------------------------------------------------------
-- The lock
-- ---------------------------------------------------------------

-- Last day of the latest closed month, or null when nothing is closed.
create function private.locked_through(hid uuid)
returns date
language sql stable security definer set search_path = ''
as $$
  select (max(c.month) + interval '1 month' - interval '1 day')::date
  from public.ledger_closings c
  where c.household_id = hid and c.status = 'closed';
$$;

-- Refuses any change to a transaction or sale dated in a closed month.
-- Two things still pass: deleting the whole household, and the "set null"
-- that follows deleting a category or account (the snapshot keeps the names).
create function private.guard_closed_month()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_lock date;
  v_hid  uuid := case when tg_op = 'DELETE' then old.household_id else new.household_id end;
  v_old  jsonb;
  v_new  jsonb;
begin
  v_lock := private.locked_through(v_hid);
  if v_lock is null then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'INSERT' then
    if new.date <= v_lock then
      raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.date <= v_lock and exists (select 1 from public.households h where h.id = old.household_id) then
      raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
    end if;
    return old;
  end if;

  -- UPDATE
  if old.date <= v_lock or new.date <= v_lock then
    v_old := to_jsonb(old) - 'category_id' - 'account_id';
    v_new := to_jsonb(new) - 'category_id' - 'account_id';
    if v_new = v_old
       and (to_jsonb(new) -> 'category_id' is null or jsonb_typeof(to_jsonb(new) -> 'category_id') = 'null'
            or to_jsonb(new) -> 'category_id' = to_jsonb(old) -> 'category_id')
       and (new.account_id is null or new.account_id is not distinct from old.account_id) then
      return new;
    end if;
    raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
  end if;
  return new;
end;
$$;

create trigger transactions_closed_month
  before insert or update or delete on public.transactions
  for each row execute function private.guard_closed_month();
create trigger sales_closed_month
  before insert or update or delete on public.sales
  for each row execute function private.guard_closed_month();

-- ---------------------------------------------------------------
-- Figures for one month (shared by the draft view and the snapshot)
-- ---------------------------------------------------------------
create function private.period_figures(p_household uuid, p_month date)
returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  m0 date := date_trunc('month', p_month)::date;
  m1 date := (date_trunc('month', p_month) + interval '1 month')::date;
  v_accounts jsonb;
  v_totals   jsonb;
  v_cats     jsonb;
  v_realized numeric;
  v_check    jsonb;
  v_income   numeric;
  v_expense  numeric;
  v_invest   numeric;
begin
  -- one row per account, plus "Unassigned" when entries without an account exist
  with acc_rows as (
    select a.id as account_id, a.name, a.sort_order, a.archived, a.opening_balance as base
    from public.accounts a where a.household_id = p_household
    union all
    select null, 'Unassigned', 1000000, false, 0
    where exists (select 1 from public.transactions t
                  where t.household_id = p_household and t.account_id is null and t.date < m1)
  ),
  figs as (
    select r.account_id, r.name, r.sort_order, r.archived,
      r.base + coalesce(sum(case when t.date < m0 then
        case when t.type in ('income', 'transfer-in') then t.amount else -t.amount end end), 0) as opening,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'income'), 0)       as income,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'expense'), 0)      as expense,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'invest'), 0)       as invest,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'transfer-in'), 0)  as transfer_in,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'transfer-out'), 0) as transfer_out
    from acc_rows r
    left join public.transactions t
      on t.household_id = p_household and t.date < m1
     and t.account_id is not distinct from r.account_id
    group by r.account_id, r.name, r.sort_order, r.archived, r.base
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'account_id', account_id, 'name', name, 'sort_order', sort_order, 'archived', archived,
      'opening', opening, 'income', income, 'expense', expense, 'invest', invest,
      'transfer_in', transfer_in, 'transfer_out', transfer_out,
      'closing', opening + income + transfer_in - expense - invest - transfer_out
    ) order by sort_order, name), '[]'),
    jsonb_build_object(
      'opening', coalesce(sum(opening), 0), 'income', coalesce(sum(income), 0),
      'expense', coalesce(sum(expense), 0), 'invest', coalesce(sum(invest), 0),
      'transfer_in', coalesce(sum(transfer_in), 0), 'transfer_out', coalesce(sum(transfer_out), 0),
      'closing', coalesce(sum(opening + income + transfer_in - expense - invest - transfer_out), 0))
  into v_accounts, v_totals
  from figs;

  v_income  := (v_totals ->> 'income')::numeric;
  v_expense := (v_totals ->> 'expense')::numeric;
  v_invest  := (v_totals ->> 'invest')::numeric;

  select coalesce(jsonb_agg(jsonb_build_object('name', name, 'amount', amount) order by amount desc), '[]')
  into v_cats
  from (
    select coalesce(c.name, 'Other') as name, sum(t.amount) as amount
    from public.transactions t
    left join public.categories c on c.id = t.category_id
    where t.household_id = p_household and t.type = 'expense' and t.date >= m0 and t.date < m1
    group by coalesce(c.name, 'Other')
  ) x;

  select coalesce(sum(s.realized_pl), 0) into v_realized
  from public.sales s
  where s.household_id = p_household and s.date >= m0 and s.date < m1;

  select jsonb_build_object(
    'entries',       count(*),
    'uncategorised', count(*) filter (where t.category_id is null and t.type not like 'transfer%'),
    'unassigned',    count(*) filter (where t.account_id is null))
  into v_check
  from public.transactions t
  where t.household_id = p_household and t.date >= m0 and t.date < m1;

  return jsonb_build_object(
    'month', m0,
    'accounts', v_accounts,
    'totals', v_totals,
    'savings_rate', case when v_income > 0 then round((v_income - v_expense - v_invest) / v_income * 100, 1) end,
    'realized_pl', v_realized,
    'by_category', v_cats,
    'checklist', v_check
  );
end;
$$;

-- ---------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------

-- Live (draft) figures for a month, plus whether it can be closed now.
create function public.period_statement(p_household uuid, p_month date)
returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  m0     date := date_trunc('month', p_month)::date;
  v_lock date;
  v_today date := (now() at time zone 'Asia/Jakarta')::date;
  v_next date;
  v_why  text := null;
begin
  if not private.is_member(p_household) then
    raise exception 'Not a member of this household';
  end if;
  v_lock := private.locked_through(p_household);
  v_next := case when v_lock is null then null else (v_lock + 1) end;

  if v_lock is not null and m0 <= v_lock then
    v_why := 'This month is already closed.';
  elsif (m0 + interval '1 month')::date > v_today then
    v_why := 'This month has not ended yet.';
  elsif v_next is not null and m0 <> v_next then
    v_why := 'Close ' || to_char(v_next, 'FMMonth YYYY') || ' first.';
  elsif not private.is_owner(p_household) then
    v_why := 'Only an owner can close a month.';
  end if;

  return private.period_figures(p_household, m0) || jsonb_build_object(
    'locked_through', v_lock,
    'can_close', v_why is null,
    'blocked_reason', v_why
  );
end;
$$;

-- Close a month: owner only, by hand. p_bank maps account id -> real bank
-- balance at month end (required for every active account); p_notes maps
-- account id -> why the bank and the books differ (required when they do).
create function public.close_period(
  p_household       uuid,
  p_month           date,
  p_bank            jsonb   default '{}',
  p_notes           jsonb   default '{}',
  p_note            text    default '',
  p_portfolio_value numeric default null,
  p_unrealized      numeric default null
)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  m0        date := date_trunc('month', p_month)::date;
  v_today   date := (now() at time zone 'Asia/Jakarta')::date;
  v_lock    date;
  v_fig     jsonb;
  v_acc     jsonb;
  v_bank    numeric;
  v_diff    numeric;
  v_noteacc text;
  v_version int;
  v_id      uuid;
  v_rows    jsonb := '[]';
begin
  if not private.is_owner(p_household) then
    raise exception 'Only an owner can close a month';
  end if;
  -- one close at a time per household
  perform 1 from public.households where id = p_household for update;

  if (m0 + interval '1 month')::date > v_today then
    raise exception '% has not ended yet', to_char(m0, 'FMMonth YYYY');
  end if;
  v_lock := private.locked_through(p_household);
  if v_lock is not null and m0 <= v_lock then
    raise exception '% is already closed', to_char(m0, 'FMMonth YYYY');
  end if;
  if v_lock is not null and m0 <> v_lock + 1 then
    raise exception 'Close % first', to_char(v_lock + 1, 'FMMonth YYYY');
  end if;

  v_fig := private.period_figures(p_household, m0);

  for v_acc in select * from jsonb_array_elements(v_fig -> 'accounts') loop
    v_bank := null; v_diff := null; v_noteacc := '';
    if v_acc ->> 'account_id' is not null then
      v_bank := nullif(trim(coalesce(p_bank ->> (v_acc ->> 'account_id'), '')), '')::numeric;
      v_noteacc := trim(coalesce(p_notes ->> (v_acc ->> 'account_id'), ''));
      if v_bank is null and not (v_acc ->> 'archived')::boolean then
        raise exception 'Enter the bank balance for %', v_acc ->> 'name';
      end if;
      if v_bank is not null then
        v_diff := v_bank - (v_acc ->> 'closing')::numeric;
        if v_diff <> 0 and v_noteacc = '' then
          raise exception '% differs from the bank by %. Add a note or an adjusting entry.',
            v_acc ->> 'name', v_diff;
        end if;
      end if;
    end if;
    v_rows := v_rows || jsonb_build_object('acc', v_acc, 'bank', v_bank, 'diff', v_diff, 'note', v_noteacc);
  end loop;

  select coalesce(max(version), 0) + 1 into v_version
  from public.ledger_closings where household_id = p_household and month = m0;

  insert into public.ledger_closings
    (household_id, month, version, status, opening, income, expense, invest, transfer_in, transfer_out,
     closing, savings_rate, realized_pl, portfolio_value, unrealized_pl, by_category, checklist, note)
  values
    (p_household, m0, v_version, 'closed',
     (v_fig #>> '{totals,opening}')::numeric, (v_fig #>> '{totals,income}')::numeric,
     (v_fig #>> '{totals,expense}')::numeric, (v_fig #>> '{totals,invest}')::numeric,
     (v_fig #>> '{totals,transfer_in}')::numeric, (v_fig #>> '{totals,transfer_out}')::numeric,
     (v_fig #>> '{totals,closing}')::numeric, (v_fig ->> 'savings_rate')::numeric,
     (v_fig ->> 'realized_pl')::numeric, p_portfolio_value, p_unrealized,
     v_fig -> 'by_category', v_fig -> 'checklist', coalesce(trim(p_note), ''))
  returning id into v_id;

  insert into public.ledger_closing_accounts
    (closing_id, household_id, account_id, account_name, sort_order, opening, income, expense, invest,
     transfer_in, transfer_out, closing, bank_balance, difference, difference_note)
  select v_id, p_household, (r #>> '{acc,account_id}')::uuid, r #>> '{acc,name}', (r #>> '{acc,sort_order}')::int,
    (r #>> '{acc,opening}')::numeric, (r #>> '{acc,income}')::numeric, (r #>> '{acc,expense}')::numeric,
    (r #>> '{acc,invest}')::numeric, (r #>> '{acc,transfer_in}')::numeric, (r #>> '{acc,transfer_out}')::numeric,
    (r #>> '{acc,closing}')::numeric, (r ->> 'bank')::numeric, (r ->> 'diff')::numeric, coalesce(r ->> 'note', '')
  from jsonb_array_elements(v_rows) as e(r);

  insert into public.ledger_closing_events (household_id, month, version, action)
  values (p_household, m0, v_version, 'close');

  return v_id;
end;
$$;

-- Reopen the latest closed month (owner only, reason required).
-- Its snapshot is kept as 'superseded'; closing again makes a new version.
create function public.reopen_period(p_household uuid, p_month date, p_reason text)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  m0        date := date_trunc('month', p_month)::date;
  v_latest  date;
  v_version int;
begin
  if not private.is_owner(p_household) then
    raise exception 'Only an owner can reopen a month';
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Say why the month is being reopened';
  end if;
  perform 1 from public.households where id = p_household for update;

  select max(month) into v_latest
  from public.ledger_closings where household_id = p_household and status = 'closed';
  if v_latest is null or m0 <> v_latest then
    raise exception 'Only the latest closed month (%) can be reopened', coalesce(to_char(v_latest, 'FMMonth YYYY'), 'none');
  end if;

  update public.ledger_closings set status = 'superseded'
  where household_id = p_household and month = m0 and status = 'closed'
  returning version into v_version;

  insert into public.ledger_closing_events (household_id, month, version, action, reason)
  values (p_household, m0, v_version, 'reopen', trim(p_reason));
end;
$$;

revoke all on function private.locked_through(uuid) from public;
revoke all on function private.guard_closed_month() from public;
revoke all on function private.period_figures(uuid, date) from public;
grant execute on function private.locked_through(uuid) to authenticated, service_role;

revoke all on function public.period_statement(uuid, date) from public, anon;
revoke all on function public.close_period(uuid, date, jsonb, jsonb, text, numeric, numeric) from public, anon;
revoke all on function public.reopen_period(uuid, date, text) from public, anon;
grant execute on function public.period_statement(uuid, date) to authenticated;
grant execute on function public.close_period(uuid, date, jsonb, jsonb, text, numeric, numeric) to authenticated;
grant execute on function public.reopen_period(uuid, date, text) to authenticated;

-- ====================================================================
-- 20261118000000_plans.sql
-- ====================================================================

-- V2.5: plans (savings goals) and in-app notifications.
-- A plan has a target amount and date; contributions record money set aside.
-- Notifications are rows in public.notifications, created by the database:
--   * right after a contribution (milestones 25/50/75/100%),
--   * by check_notifications(), which the app calls when it opens,
--   * twice a day by pg_cron (07:00 and 19:00 WIB) when pg_cron is available.
-- Push delivery (push_subscriptions + an Edge Function that sends unsent rows)
-- is the next step; this file only stores the subscriptions.
-- The closing statement gains a per-plan section (ledger_closings.plans).
-- Needs 20261117000000_ledger_closing.sql (contributions follow the month lock).
-- Run this once in the SQL Editor (or with `supabase db push`).

-- ---------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------
create table public.plans (
  id            uuid primary key default gen_random_uuid(),
  household_id  uuid not null references public.households (id) on delete cascade,
  name          text not null check (length(trim(name)) > 0),
  icon          text not null default '🎯',
  note          text not null default '',
  target_amount numeric(18, 2) not null check (target_amount > 0),
  start_date    date not null default ((now() at time zone 'Asia/Jakarta')::date),
  target_date   date not null,
  account_id    uuid references public.accounts (id) on delete set null,
  status        text not null default 'active' check (status in ('active', 'paused', 'achieved', 'cancelled')),
  achieved_at   timestamptz,    -- set by the database when status becomes 'achieved'
  behind_since  date,           -- set by the daily check; one "behind" notification per streak
  created_by    uuid references auth.users (id) on delete set null default auth.uid(),
  created_at    timestamptz not null default now(),
  check (target_date > start_date)
);
create index plans_household_idx on public.plans (household_id, status);

create table public.plan_contributions (
  id             uuid primary key default gen_random_uuid(),
  household_id   uuid not null references public.households (id) on delete cascade,
  plan_id        uuid not null references public.plans (id) on delete cascade,
  date           date not null default ((now() at time zone 'Asia/Jakarta')::date),
  amount         numeric(18, 2) not null check (amount > 0),
  note           text not null default '',
  transaction_id uuid unique references public.transactions (id) on delete set null,
  created_by     uuid references auth.users (id) on delete set null default auth.uid(),
  created_at     timestamptz not null default now()
);
create index plan_contributions_plan_idx on public.plan_contributions (plan_id, date);
create index plan_contributions_household_idx on public.plan_contributions (household_id, date);

create table public.notifications (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  user_id      uuid not null references auth.users (id) on delete cascade,
  kind         text not null check (kind in
                 ('plan_milestone', 'plan_achieved', 'plan_behind', 'plan_deadline', 'plan_overdue', 'plan_monthly', 'month_close')),
  subject_id   uuid,            -- the plan; null for month_close
  period_key   text not null,   -- makes each notification happen once: '50', '7d:2026-12-31', '2026-11', ...
  title        text not null,
  body         text not null default '',
  link         text not null default '', -- 'plan:<id>' or 'statement:<YYYY-MM-01>'
  created_at   timestamptz not null default now(),
  sent_at      timestamptz,     -- set by push delivery
  read_at      timestamptz,
  unique nulls not distinct (user_id, kind, subject_id, period_key)
);
create index notifications_user_idx on public.notifications (user_id, created_at desc);
create index notifications_unsent_idx on public.notifications (created_at) where sent_at is null;

-- Missing row = default: owners get everything, other members nothing.
create table public.notification_prefs (
  user_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  kind    text not null check (kind in
            ('plan_milestone', 'plan_achieved', 'plan_behind', 'plan_deadline', 'plan_overdue', 'plan_monthly', 'month_close')),
  enabled boolean not null,
  primary key (user_id, kind)
);

-- One row per device that allowed Web Push. Saved through save_push_subscription().
create table public.push_subscriptions (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade default auth.uid(),
  endpoint   text not null unique,
  p256dh     text not null,
  auth       text not null,
  user_agent text not null default '',
  created_at timestamptz not null default now()
);
create index push_subscriptions_user_idx on public.push_subscriptions (user_id);

-- The closing statement keeps each plan's month (FR-PLN-11).
alter table public.ledger_closings add column plans jsonb not null default '[]';

-- ---------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------
alter table public.plans              enable row level security;
alter table public.plan_contributions enable row level security;
alter table public.notifications      enable row level security;
alter table public.notification_prefs enable row level security;
alter table public.push_subscriptions enable row level security;

create policy plans_all on public.plans
  for all to authenticated
  using (private.is_member(household_id)) with check (private.is_member(household_id));
create policy plan_contributions_all on public.plan_contributions
  for all to authenticated
  using (private.is_member(household_id)) with check (private.is_member(household_id));

-- Each user sees, marks read and clears only their own notifications;
-- only the database creates them.
create policy notifications_own_select on public.notifications
  for select to authenticated using (user_id = (select auth.uid()));
create policy notifications_own_update on public.notifications
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy notifications_own_delete on public.notifications
  for delete to authenticated using (user_id = (select auth.uid()));
create policy notification_prefs_own on public.notification_prefs
  for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy push_subscriptions_own_select on public.push_subscriptions
  for select to authenticated using (user_id = (select auth.uid()));
create policy push_subscriptions_own_delete on public.push_subscriptions
  for delete to authenticated using (user_id = (select auth.uid()));

revoke all on public.plans, public.plan_contributions, public.notifications,
  public.notification_prefs, public.push_subscriptions from anon;
-- Supabase grants everything on new tables by default; take it back and
-- give only what the app needs. behind_since and achieved_at belong to the database.
revoke all on public.plans, public.plan_contributions, public.notifications,
  public.notification_prefs, public.push_subscriptions from authenticated;
grant select, insert, update, delete on public.plan_contributions, public.notification_prefs to authenticated;
grant select, insert, delete on public.plans to authenticated;
grant update (name, icon, note, target_amount, start_date, target_date, account_id, status)
  on public.plans to authenticated;
grant select, delete on public.notifications, public.push_subscriptions to authenticated;
grant update (read_at) on public.notifications to authenticated;
grant all on public.plans, public.plan_contributions, public.notifications,
  public.notification_prefs, public.push_subscriptions to service_role;

-- ---------------------------------------------------------------
-- Rules
-- ---------------------------------------------------------------

-- Plans: the linked account must be in the same household, the target date
-- must be in the future when it is set, and status drives achieved_at.
create function private.plan_rules()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_today date := (now() at time zone 'Asia/Jakarta')::date;
begin
  if tg_op = 'UPDATE' and new.household_id <> old.household_id then
    raise exception 'A plan cannot move to another household';
  end if;
  if new.account_id is not null and not exists (
       select 1 from public.accounts a where a.id = new.account_id and a.household_id = new.household_id) then
    raise exception 'That account is not in this household';
  end if;
  if (tg_op = 'INSERT' or new.target_date <> old.target_date)
     and new.target_date <= v_today and new.status in ('active', 'paused') then
    raise exception 'The target date must be in the future';
  end if;

  if tg_op = 'INSERT' then
    new.behind_since := null;
  end if;
  if new.status = 'achieved' then
    new.achieved_at := coalesce(case when tg_op = 'UPDATE' and old.status = 'achieved' then old.achieved_at end, now());
  else
    new.achieved_at := null;
  end if;
  -- a fresh start: pausing, cancelling or moving the date ends a "behind" streak
  if new.status <> 'active' or (tg_op = 'UPDATE' and new.target_date <> old.target_date) then
    new.behind_since := null;
  end if;
  return new;
end;
$$;

create trigger plans_rules
  before insert or update on public.plans
  for each row execute function private.plan_rules();

-- A plan with contributions can only be cancelled, not deleted.
create function private.guard_plan_delete()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if exists (select 1 from public.households h where h.id = old.household_id)
     and exists (select 1 from public.plan_contributions c where c.plan_id = old.id) then
    raise exception 'This plan has money in it. Cancel it instead of deleting it.';
  end if;
  return old;
end;
$$;

create trigger plans_no_delete_with_money
  before delete on public.plans
  for each row execute function private.guard_plan_delete();

-- Contributions: the plan and the linked transaction must be in the same
-- household; cancelled plans take no new money.
create function private.contribution_rules()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_plan public.plans;
begin
  select * into v_plan from public.plans where id = new.plan_id;
  if v_plan.id is null or v_plan.household_id <> new.household_id then
    raise exception 'That plan is not in this household';
  end if;
  if v_plan.status = 'cancelled' and (tg_op = 'INSERT' or new.plan_id <> old.plan_id) then
    raise exception 'This plan is cancelled. Resume it first.';
  end if;
  if new.transaction_id is not null
     and (tg_op = 'INSERT' or new.transaction_id is distinct from old.transaction_id)
     and not exists (select 1 from public.transactions t
                     where t.id = new.transaction_id and t.household_id = new.household_id) then
    raise exception 'That transaction is not in this household';
  end if;
  return new;
end;
$$;

create trigger plan_contributions_rules
  before insert or update on public.plan_contributions
  for each row execute function private.contribution_rules();

-- Contributions dated in a closed month are locked like transactions.
-- Two things still pass: deleting the whole household, and the "set null"
-- that follows deleting the linked transaction.
create function private.guard_closed_contribution()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_hid  uuid := case when tg_op = 'DELETE' then old.household_id else new.household_id end;
  v_lock date := private.locked_through(v_hid);
begin
  if v_lock is null then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'INSERT' then
    if new.date <= v_lock then
      raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.date <= v_lock and exists (select 1 from public.households h where h.id = old.household_id) then
      raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
    end if;
    return old;
  end if;

  -- UPDATE
  if old.date <= v_lock or new.date <= v_lock then
    if new.transaction_id is null
       and to_jsonb(new) - 'transaction_id' = to_jsonb(old) - 'transaction_id' then
      return new;
    end if;
    raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
  end if;
  return new;
end;
$$;

create trigger plan_contributions_closed_month
  before insert or update or delete on public.plan_contributions
  for each row execute function private.guard_closed_contribution();

-- ---------------------------------------------------------------
-- Notification helpers
-- ---------------------------------------------------------------
create function private.rp(v numeric)
returns text
language sql immutable set search_path = ''
as $$
  select case when v < 0 then '−' else '' end || 'Rp '
    || replace(to_char(abs(round(v)), 'FM999,999,999,999,990'), ',', '.');
$$;

create function private.month_name(d date)
returns text
language sql immutable set search_path = ''
as $$
  select (array['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus',
                'September','Oktober','November','Desember'])[extract(month from d)::int]
    || ' ' || extract(year from d)::int;
$$;

create function private.long_date(d date)
returns text
language sql immutable set search_path = ''
as $$
  select extract(day from d)::int || ' ' || private.month_name(d);
$$;

-- Owners get every kind unless they turned it off; other members only
-- the kinds they turned on. month_close goes to owners only.
create function private.notify(
  p_household uuid, p_kind text, p_subject uuid, p_key text, p_title text, p_body text, p_link text
)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  insert into public.notifications (household_id, user_id, kind, subject_id, period_key, title, body, link)
  select p_household, m.user_id, p_kind, p_subject, p_key, p_title, p_body, p_link
  from public.members m
  left join public.notification_prefs np on np.user_id = m.user_id and np.kind = p_kind
  where m.household_id = p_household
    and case when m.role = 'owner' then coalesce(np.enabled, true)
             else p_kind <> 'month_close' and coalesce(np.enabled, false) end
  on conflict (user_id, kind, subject_id, period_key) do nothing;
end;
$$;

-- Check one plan. p_daily = false runs only the milestone check (after a
-- contribution); true also runs the date-based checks (FR-PLN-09).
create function private.check_plan(p_plan uuid, p_daily boolean)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  p          public.plans;
  v_today    date := (now() at time zone 'Asia/Jakarta')::date;
  v_saved    numeric;
  v_left_amt numeric;
  v_pct      numeric;
  v_mile     int;
  v_total    int;
  v_elapsed  int;
  v_expected numeric;
  v_days     int;
  v_months   int;
  v_needed   numeric;
  v_thismon  numeric;
  v_link     text;
  v_name     text;
begin
  select * into p from public.plans where id = p_plan;
  if p.id is null or p.status in ('achieved', 'cancelled') then return; end if;
  v_link := 'plan:' || p.id;
  v_name := p.icon || ' ' || p.name;

  select coalesce(sum(amount), 0) into v_saved from public.plan_contributions where plan_id = p.id;
  v_left_amt := greatest(p.target_amount - v_saved, 0);
  v_pct := v_saved / p.target_amount * 100;

  -- milestones: only the highest one reached, once
  v_mile := case when v_pct >= 100 then 100 when v_pct >= 75 then 75 when v_pct >= 50 then 50
                 when v_pct >= 25 then 25 else 0 end;
  if v_mile = 100 then
    update public.plans set status = 'achieved' where id = p.id;
    perform private.notify(p.household_id, 'plan_achieved', p.id, '100',
      v_name || ' reached its target',
      private.rp(v_saved) || ' saved of ' || private.rp(p.target_amount) || '.', v_link);
    return;
  elsif v_mile > 0 then
    perform private.notify(p.household_id, 'plan_milestone', p.id, v_mile::text,
      v_name || ' is ' || v_mile || '% there',
      private.rp(v_saved) || ' saved of ' || private.rp(p.target_amount) || '.', v_link);
  end if;

  -- paused plans get no date-based reminders
  if not p_daily or p.status <> 'active' then return; end if;

  v_days   := p.target_date - v_today;
  v_months := greatest(1, (extract(year from age(p.target_date, v_today)) * 12
                           + extract(month from age(p.target_date, v_today))
                           + case when extract(day from age(p.target_date, v_today)) > 0 then 1 else 0 end)::int);
  v_needed := v_left_amt / v_months;

  -- keys carry the target date, so moving the date re-arms these
  if v_days < 0 then
    perform private.notify(p.household_id, 'plan_overdue', p.id, 'overdue:' || p.target_date,
      v_name || ' passed its target date',
      private.rp(v_left_amt) || ' still to go. Move the date or add money.', v_link);
    return;
  end if;

  if v_days <= 7 then
    perform private.notify(p.household_id, 'plan_deadline', p.id, '7d:' || p.target_date,
      v_name || ': ' || case when v_days = 0 then 'due today'
                             else v_days || ' day' || case when v_days = 1 then '' else 's' end || ' left' end,
      private.rp(v_left_amt) || ' still to go.', v_link);
  elsif v_days <= 30 then
    perform private.notify(p.household_id, 'plan_deadline', p.id, '30d:' || p.target_date,
      v_name || ': ' || v_days || ' days left',
      private.rp(v_left_amt) || ' still to go.', v_link);
  end if;

  -- behind: below the straight line from start to target by more than 5% of
  -- the target (FR-PLN-05). One notification each time the plan falls behind.
  v_total    := greatest(p.target_date - p.start_date, 1);
  v_elapsed  := least(greatest(v_today - p.start_date, 0), v_total);
  v_expected := p.target_amount * v_elapsed / v_total;
  if v_saved < v_expected - p.target_amount * 0.05 then
    if p.behind_since is null then
      update public.plans set behind_since = v_today where id = p.id;
      perform private.notify(p.household_id, 'plan_behind', p.id, v_today::text,
        v_name || ' is falling behind',
        'Saved ' || private.rp(v_saved) || '; by now it should be about '
          || private.rp(v_expected) || '. Aim for ' || private.rp(v_needed) || ' a month.', v_link);
    end if;
  elsif p.behind_since is not null then
    update public.plans set behind_since = null where id = p.id;
  end if;

  -- monthly reminder from the 25th, if this month's share is not in yet
  if extract(day from v_today) >= 25 then
    select coalesce(sum(amount), 0) into v_thismon from public.plan_contributions
    where plan_id = p.id and date >= date_trunc('month', v_today)::date;
    if v_needed - v_thismon > 0 then
      perform private.notify(p.household_id, 'plan_monthly', p.id, to_char(v_today, 'YYYY-MM'),
        v_name || ': ' || private.rp(v_needed - v_thismon) || ' to go this month',
        'Putting in ' || private.rp(v_needed) || ' a month reaches ' || private.rp(p.target_amount)
          || ' by ' || private.long_date(p.target_date) || '.', v_link);
    end if;
  end if;
end;
$$;

-- Daily checks for one household: every plan, plus the month-close reminder
-- (FR-CLS-12: last day of the month from 19:00 WIB, then days 1, 3 and 7 of
-- the next month while the month that should be closed next is still open).
create function private.check_household(p_household uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_plan   uuid;
  v_now    timestamp := now() at time zone 'Asia/Jakarta';
  v_today  date := v_now::date;
  v_this   date := date_trunc('month', v_now)::date;
  v_lock   date := private.locked_through(p_household);
  v_next   date;
  v_day    int := extract(day from v_now)::int;
  v_last   boolean := (v_today + 1) = (v_this + interval '1 month')::date;
begin
  for v_plan in select id from public.plans where household_id = p_household and status in ('active', 'paused') loop
    perform private.check_plan(v_plan, true);
  end loop;

  -- the month that should be closed next; none until the ledger has entries
  if v_lock is not null then
    v_next := v_lock + 1;
  elsif exists (select 1 from public.transactions t where t.household_id = p_household and t.date < v_this) then
    v_next := (v_this - interval '1 month')::date;
  end if;

  -- last day of a month, when it is the next one to close
  if v_last and extract(hour from v_now) >= 19
     and (v_lock + 1 = v_this
          or (v_lock is null and v_next is null
              and exists (select 1 from public.transactions t where t.household_id = p_household))) then
    perform private.notify(p_household, 'month_close', null, to_char(v_this, 'YYYY-MM') || '-last',
      'Time to close ' || private.month_name(v_this),
      'The month ends tonight. Close it from tomorrow once the last entries are in.',
      'statement:' || to_char(v_this, 'YYYY-MM-DD'));
  end if;

  -- only the latest reminder that applies, so a late first run sends one, not three
  if v_next is not null and v_next < v_this then
    if v_day >= 7 then
      perform private.notify(p_household, 'month_close', null, to_char(v_next, 'YYYY-MM') || '-d7',
        'Last reminder: close ' || private.month_name(v_next),
        'It has been a week since the month ended.', 'statement:' || to_char(v_next, 'YYYY-MM-DD'));
    elsif v_day >= 3 then
      perform private.notify(p_household, 'month_close', null, to_char(v_next, 'YYYY-MM') || '-d3',
        private.month_name(v_next) || ' is still open',
        'Close it so its statement is saved and its entries are locked.', 'statement:' || to_char(v_next, 'YYYY-MM-DD'));
    else
      perform private.notify(p_household, 'month_close', null, to_char(v_next, 'YYYY-MM') || '-d1',
        'Close ' || private.month_name(v_next),
        'Check the figures and bank balances, then lock the month.', 'statement:' || to_char(v_next, 'YYYY-MM-DD'));
    end if;
  end if;
end;
$$;

-- After a contribution, check milestones at once (FR-NTF-08).
create function private.after_contribution()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  perform private.check_plan(new.plan_id, false);
  return null;
end;
$$;

create trigger plan_contributions_milestones
  after insert or update of amount, plan_id on public.plan_contributions
  for each row execute function private.after_contribution();

-- ---------------------------------------------------------------
-- Plans in the closing statement (FR-PLN-11)
-- ---------------------------------------------------------------

-- Per plan: money put in during the month and progress at month end.
-- Lists plans that got money that month, plus plans running at month end.
create function private.plan_figures(p_household uuid, p_month date)
returns jsonb
language sql stable security definer set search_path = ''
as $$
  with b as (
    select date_trunc('month', p_month)::date as m0,
           (date_trunc('month', p_month) + interval '1 month')::date as m1
  ),
  f as (
    select p.id, p.name, p.icon, p.status, p.target_amount, p.target_date,
      coalesce(sum(c.amount) filter (where c.date >= b.m0), 0) as contributed,
      coalesce(sum(c.amount), 0) as saved
    from public.plans p
    cross join b
    left join public.plan_contributions c on c.plan_id = p.id and c.date < b.m1
    where p.household_id = p_household and p.start_date < b.m1
    group by p.id, b.m0, b.m1
    having coalesce(sum(c.amount) filter (where c.date >= b.m0), 0) > 0
        or p.status in ('active', 'paused')
        or (p.status = 'achieved' and p.achieved_at >= b.m1)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'plan_id', id, 'name', name, 'icon', icon, 'status', status,
    'target', target_amount, 'target_date', target_date,
    'contributed', contributed, 'saved', saved,
    'progress', round(least(saved / target_amount * 100, 100), 1)
  ) order by target_date, name), '[]')
  from f;
$$;

-- period_statement and close_period keep calling private.period_figures;
-- the old body becomes period_figures_base and the new one adds 'plans'.
alter function private.period_figures(uuid, date) rename to period_figures_base;

create function private.period_figures(p_household uuid, p_month date)
returns jsonb
language sql stable security definer set search_path = ''
as $$
  select private.period_figures_base(p_household, p_month)
    || jsonb_build_object('plans', private.plan_figures(p_household, p_month));
$$;

-- Store the plan section with each closing, and clear that month's
-- close reminders once it is closed.
create function private.closing_plans()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  new.plans := private.plan_figures(new.household_id, new.month);
  return new;
end;
$$;

create trigger ledger_closings_plans
  before insert on public.ledger_closings
  for each row execute function private.closing_plans();

create function private.closing_clears_reminders()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  update public.notifications set read_at = now()
  where household_id = new.household_id and kind = 'month_close' and read_at is null
    and period_key like to_char(new.month, 'YYYY-MM') || '-%';
  return null;
end;
$$;

create trigger ledger_closings_clear_reminders
  after insert on public.ledger_closings
  for each row execute function private.closing_clears_reminders();

-- ---------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------

-- Called by the app when it opens: runs the daily checks for this household
-- and returns the caller's unread count. Safe to call often; each
-- notification is created only once.
create function public.check_notifications(p_household uuid)
returns int
language plpgsql security definer set search_path = ''
as $$
declare
  v_unread int;
begin
  if not private.is_member(p_household) then
    raise exception 'Not a member of this household';
  end if;
  perform private.check_household(p_household);
  select count(*) into v_unread from public.notifications
  where user_id = auth.uid() and read_at is null;
  return v_unread;
end;
$$;

-- Saves this device's Web Push subscription for the caller. An endpoint
-- belongs to one browser, so it moves to whoever signed in there last.
create function public.save_push_subscription(p_endpoint text, p_p256dh text, p_auth text, p_user_agent text default '')
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Sign in first';
  end if;
  if coalesce(p_endpoint, '') !~ '^https://' or coalesce(p_p256dh, '') = '' or coalesce(p_auth, '') = '' then
    raise exception 'Incomplete push subscription';
  end if;
  insert into public.push_subscriptions (user_id, endpoint, p256dh, auth, user_agent)
  values (auth.uid(), p_endpoint, p_p256dh, p_auth, left(coalesce(p_user_agent, ''), 300))
  on conflict (endpoint) do update
    set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth,
        user_agent = excluded.user_agent, created_at = now();
end;
$$;

-- Called by pg_cron: runs the daily checks for every household and trims
-- old notifications (read ones after 90 days, all after a year).
create function public.run_notifications()
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_h uuid;
begin
  for v_h in select id from public.households loop
    perform private.check_household(v_h);
  end loop;
  delete from public.notifications
  where (read_at is not null and created_at < now() - interval '90 days')
     or created_at < now() - interval '365 days';
end;
$$;

revoke all on function private.plan_rules() from public;
revoke all on function private.guard_plan_delete() from public;
revoke all on function private.contribution_rules() from public;
revoke all on function private.guard_closed_contribution() from public;
revoke all on function private.rp(numeric) from public;
revoke all on function private.month_name(date) from public;
revoke all on function private.long_date(date) from public;
revoke all on function private.notify(uuid, text, uuid, text, text, text, text) from public;
revoke all on function private.check_plan(uuid, boolean) from public;
revoke all on function private.check_household(uuid) from public;
revoke all on function private.after_contribution() from public;
revoke all on function private.plan_figures(uuid, date) from public;
revoke all on function private.period_figures(uuid, date) from public;
revoke all on function private.closing_plans() from public;
revoke all on function private.closing_clears_reminders() from public;
revoke all on function public.check_notifications(uuid) from public, anon;
revoke all on function public.save_push_subscription(text, text, text, text) from public, anon;
revoke all on function public.run_notifications() from public, anon, authenticated;
grant execute on function public.check_notifications(uuid) to authenticated;
grant execute on function public.save_push_subscription(text, text, text, text) to authenticated;
grant execute on function public.run_notifications() to service_role;

-- ---------------------------------------------------------------
-- Live bell count (optional): stream notifications over Realtime.
-- ---------------------------------------------------------------
do $$
begin
  alter publication supabase_realtime add table public.notifications;
exception when others then
  raise notice 'Realtime not set up for notifications (%). The app still reads them when it opens.', sqlerrm;
end;
$$;

-- ---------------------------------------------------------------
-- Schedule (optional): 07:00 and 19:00 WIB (00:00 and 12:00 UTC). Skipped
-- with a notice when pg_cron is not available; the app still runs the checks
-- when it opens. Re-running replaces the jobs of the same name.
-- ---------------------------------------------------------------
do $$
begin
  create extension if not exists pg_cron with schema pg_catalog;
  perform cron.schedule('finance-notifications-morning', '0 0 * * *', 'select public.run_notifications()');
  perform cron.schedule('finance-notifications-evening', '0 12 * * *', 'select public.run_notifications()');
exception when others then
  raise notice 'pg_cron is not set up (%). Notifications are still created when the app opens.', sqlerrm;
end;
$$;

-- ====================================================================
-- 20261119000000_plan_ledger.sql
-- ====================================================================

-- V2.6: the plan ledger, gold and stocks inside plans, and earmarks.
--
-- A plan is an earmark, not an account. Money stays in the real account
-- (plans.account_id), so account balances keep matching the bank. The plan
-- ledger records every movement of a plan:
--   deposit / withdrawal / adjustment   cash set aside, taken out, corrected
--   asset_in / asset_out                a holding (gold or stock) assigned or released
-- Plan value = cash + assigned holdings. The database values holdings at cost
-- (it has no live prices); the app values them live from the prices function.
-- Month-end market prices are stored before closing so a statement can be
-- reproduced (month_end_prices, set_month_end_prices()).
--
-- Needs 20261117000000_ledger_closing.sql and 20261118000000_plans.sql.
-- plan_contributions stays as a compatibility view over the deposit rows, so
-- the current app keeps working until it moves to plan_ledger.
-- Run this once in the SQL Editor (or with `supabase db push`).

-- ---------------------------------------------------------------
-- plan_contributions becomes plan_ledger
-- ---------------------------------------------------------------
alter table public.plan_contributions rename to plan_ledger;
alter index public.plan_contributions_plan_idx rename to plan_ledger_plan_idx;
alter index public.plan_contributions_household_idx rename to plan_ledger_household_idx;
alter policy plan_contributions_all on public.plan_ledger rename to plan_ledger_all;
alter trigger plan_contributions_rules on public.plan_ledger rename to plan_ledger_rules;
alter trigger plan_contributions_closed_month on public.plan_ledger rename to plan_ledger_closed_month;
alter trigger plan_contributions_milestones on public.plan_ledger rename to plan_ledger_milestones;

-- amounts are signed now: drop the old "amount > 0" check, whatever it was called
do $$
declare
  c record;
begin
  for c in
    select conname from pg_constraint
    where conrelid = 'public.plan_ledger'::regclass and contype = 'c'
      and pg_get_constraintdef(oid) ~* 'amount\)? *> *\(*0'
  loop
    execute format('alter table public.plan_ledger drop constraint %I', c.conname);
  end loop;
end;
$$;

alter table public.plan_ledger
  add column entry_type text not null default 'deposit'
    check (entry_type in ('deposit', 'withdrawal', 'adjustment', 'asset_in', 'asset_out')),
  add column holding_id  uuid references public.holdings (id) on delete set null,
  add column asset_type  text,           -- asset rows describe the asset themselves,
  add column ticker      text,           -- so they still read right after the lot is sold
  add column asset_name  text,
  add column quantity    numeric(18, 6), -- grams or shares
  add column unit_price  numeric(18, 2); -- price per gram / share when it was recorded

alter table public.plan_ledger add constraint plan_ledger_shape check (
  case entry_type
    when 'deposit'    then amount > 0
    when 'withdrawal' then amount < 0
    when 'adjustment' then amount <> 0
    else amount >= 0
  end
  and (entry_type in ('asset_in', 'asset_out')) = (quantity is not null)
  and (quantity is null or quantity > 0)
  and (entry_type in ('asset_in', 'asset_out')
       or (holding_id is null and asset_type is null and ticker is null
           and asset_name is null and unit_price is null))
  and (entry_type not in ('asset_in', 'asset_out')
       or (asset_type in ('gold', 'stock') and unit_price is not null and unit_price >= 0
           and ticker is not null and asset_name is not null))
);

-- ---------------------------------------------------------------
-- Holdings assigned to plans
-- ---------------------------------------------------------------
-- How much of each lot is earmarked for each plan. Changed only through
-- assign_holding_to_plan / unassign_holding_from_plan (and the sale trigger below).
create table public.plan_holdings (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  plan_id      uuid not null references public.plans (id) on delete cascade,
  holding_id   uuid not null references public.holdings (id) on delete cascade,
  quantity     numeric(18, 6) not null check (quantity > 0),
  created_by   uuid references auth.users (id) on delete set null default auth.uid(),
  created_at   timestamptz not null default now(),
  unique (plan_id, holding_id)
);
create index plan_holdings_household_idx on public.plan_holdings (household_id);
create index plan_holdings_holding_idx on public.plan_holdings (holding_id);

-- Market price of each asset on the last day of a month, saved before closing.
-- Keys are normalised the way sell_holding matches lots: ticker upper, name lower.
create table public.month_end_prices (
  household_id uuid not null references public.households (id) on delete cascade,
  month        date not null check (month = date_trunc('month', month)::date),
  asset_type   text not null check (asset_type in ('gold', 'stock')),
  ticker       text not null default '',
  name         text not null default '',
  price        numeric(18, 2) not null check (price > 0),
  created_at   timestamptz not null default now(),
  primary key (household_id, month, asset_type, ticker, name)
);

-- ---------------------------------------------------------------
-- Row-level security and grants
-- ---------------------------------------------------------------
alter table public.plan_holdings    enable row level security;
alter table public.month_end_prices enable row level security;

-- Members add and fix cash entries; asset rows come only from the functions below.
drop policy plan_ledger_all on public.plan_ledger;
create policy plan_ledger_select on public.plan_ledger
  for select to authenticated using (private.is_member(household_id));
create policy plan_ledger_insert on public.plan_ledger
  for insert to authenticated
  with check (private.is_member(household_id) and entry_type in ('deposit', 'withdrawal', 'adjustment'));
create policy plan_ledger_update on public.plan_ledger
  for update to authenticated
  using (private.is_member(household_id) and entry_type in ('deposit', 'withdrawal', 'adjustment'))
  with check (private.is_member(household_id) and entry_type in ('deposit', 'withdrawal', 'adjustment'));
create policy plan_ledger_delete on public.plan_ledger
  for delete to authenticated
  using (private.is_member(household_id) and entry_type in ('deposit', 'withdrawal', 'adjustment'));

create policy plan_holdings_select on public.plan_holdings
  for select to authenticated using (private.is_member(household_id));
create policy month_end_prices_select on public.month_end_prices
  for select to authenticated using (private.is_member(household_id));

revoke all on public.plan_ledger, public.plan_holdings, public.month_end_prices from anon;
revoke all on public.plan_ledger, public.plan_holdings, public.month_end_prices from authenticated;
grant select, insert, delete on public.plan_ledger to authenticated;
grant update (plan_id, date, amount, note, transaction_id) on public.plan_ledger to authenticated;
grant select on public.plan_holdings, public.month_end_prices to authenticated;
grant all on public.plan_ledger, public.plan_holdings, public.month_end_prices to service_role;

-- ---------------------------------------------------------------
-- Rules
-- ---------------------------------------------------------------

-- Same checks as before. A cancelled plan takes no new money or assets, but
-- money and assets can still leave it (a withdrawal, or a lot being sold).
create or replace function private.contribution_rules()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_plan public.plans;
begin
  select * into v_plan from public.plans where id = new.plan_id;
  if v_plan.id is null or v_plan.household_id <> new.household_id then
    raise exception 'That plan is not in this household';
  end if;
  if v_plan.status = 'cancelled' and new.entry_type in ('deposit', 'adjustment', 'asset_in')
     and (tg_op = 'INSERT' or new.plan_id <> old.plan_id) then
    raise exception 'This plan is cancelled. Resume it first.';
  end if;
  if new.transaction_id is not null
     and (tg_op = 'INSERT' or new.transaction_id is distinct from old.transaction_id)
     and not exists (select 1 from public.transactions t
                     where t.id = new.transaction_id and t.household_id = new.household_id) then
    raise exception 'That transaction is not in this household';
  end if;
  return new;
end;
$$;

-- Entries dated in a closed month are locked, as before. The "set null" that
-- follows deleting the linked transaction or the sold lot still passes.
create or replace function private.guard_closed_contribution()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_hid  uuid := case when tg_op = 'DELETE' then old.household_id else new.household_id end;
  v_lock date := private.locked_through(v_hid);
begin
  if v_lock is null then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'INSERT' then
    if new.date <= v_lock then
      raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.date <= v_lock and exists (select 1 from public.households h where h.id = old.household_id) then
      raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
    end if;
    return old;
  end if;

  -- UPDATE
  if old.date <= v_lock or new.date <= v_lock then
    if (new.transaction_id is null or new.transaction_id is not distinct from old.transaction_id)
       and (new.holding_id is null or new.holding_id is not distinct from old.holding_id)
       and to_jsonb(new) - 'transaction_id' - 'holding_id' = to_jsonb(old) - 'transaction_id' - 'holding_id' then
      return new;
    end if;
    raise exception 'Closed month: entries up to % are locked. An owner can reopen the month.', to_char(v_lock, 'DD Mon YYYY');
  end if;
  return new;
end;
$$;

-- A plan's cash can never go below zero.
create function private.guard_plan_cash()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_plan uuid;
begin
  for v_plan in
    select distinct x from unnest(array[
      case when tg_op <> 'INSERT' then old.plan_id end,
      case when tg_op <> 'DELETE' then new.plan_id end]) as x where x is not null
  loop
    if exists (select 1 from public.plans p join public.households h on h.id = p.household_id where p.id = v_plan)
       and private.plan_cash(v_plan) < 0 then
      raise exception 'That would take the plan below zero. Withdraw less.';
    end if;
  end loop;
  return null;
end;
$$;

create trigger plan_ledger_cash_floor
  after insert or update or delete on public.plan_ledger
  for each row execute function private.guard_plan_cash();

-- Assigned quantities: same household, never more than the lot holds.
create function private.plan_holding_rules()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_hold  public.holdings;
  v_other numeric;
begin
  if not exists (select 1 from public.plans p where p.id = new.plan_id and p.household_id = new.household_id) then
    raise exception 'That plan is not in this household';
  end if;
  select * into v_hold from public.holdings h where h.id = new.holding_id for update;
  if v_hold.id is null or v_hold.household_id <> new.household_id then
    raise exception 'That holding is not in this household';
  end if;
  select coalesce(sum(ph.quantity), 0) into v_other
  from public.plan_holdings ph where ph.holding_id = new.holding_id and ph.id <> new.id;
  if v_other + new.quantity > v_hold.quantity then
    raise exception 'Only % of this holding is free to assign', v_hold.quantity - v_other;
  end if;
  return new;
end;
$$;

create trigger plan_holdings_rules
  before insert or update on public.plan_holdings
  for each row execute function private.plan_holding_rules();

-- When a lot is sold down or deleted, take the sold quantity out of the plans
-- (newest assignment first) and record it as asset_out. The sale proceeds are
-- not moved into the plan; that is a separate decision.
create function private.release_plan_holdings()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_keep   numeric := case when tg_op = 'DELETE' then 0 else new.quantity end;
  v_total  numeric;
  v_extra  numeric;
  v_take   numeric;
  v_today  date := (now() at time zone 'Asia/Jakarta')::date;
  v_lock   date;
  v_date   date;
  r        record;
begin
  if tg_op = 'UPDATE' and new.quantity >= old.quantity then
    return new;
  end if;
  if exists (select 1 from public.households h where h.id = old.household_id) then
    select coalesce(sum(ph.quantity), 0) into v_total from public.plan_holdings ph where ph.holding_id = old.id;
    v_extra := v_total - v_keep;
    if v_extra > 0 then
      v_lock := private.locked_through(old.household_id);
      v_date := greatest(v_today, coalesce(v_lock + 1, v_today));
      for r in
        select ph.id, ph.plan_id, ph.quantity from public.plan_holdings ph
        where ph.holding_id = old.id order by ph.created_at desc, ph.id
      loop
        exit when v_extra <= 0;
        v_take := least(r.quantity, v_extra);
        if v_take >= r.quantity then
          delete from public.plan_holdings where id = r.id;
        else
          update public.plan_holdings set quantity = quantity - v_take where id = r.id;
        end if;
        insert into public.plan_ledger
          (household_id, plan_id, date, amount, note, entry_type, holding_id,
           asset_type, ticker, asset_name, quantity, unit_price)
        values
          (old.household_id, r.plan_id, v_date, round(v_take * old.buy_price, 2), 'Holding sold or removed',
           'asset_out', old.id, old.asset_type, old.ticker, old.name, v_take, old.buy_price);
        v_extra := v_extra - v_take;
      end loop;
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

create trigger holdings_release_plan_holdings
  before update of quantity or delete on public.holdings
  for each row execute function private.release_plan_holdings();

-- A plan with ledger entries or assigned holdings can only be cancelled.
create or replace function private.guard_plan_delete()
returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if exists (select 1 from public.households h where h.id = old.household_id)
     and (exists (select 1 from public.plan_ledger l where l.plan_id = old.id)
          or exists (select 1 from public.plan_holdings ph where ph.plan_id = old.id)) then
    raise exception 'This plan has money in it. Cancel it instead of deleting it.';
  end if;
  return old;
end;
$$;

-- ---------------------------------------------------------------
-- Figures
-- ---------------------------------------------------------------

-- Cash in a plan: deposits, withdrawals and adjustments.
create function private.plan_cash(p_plan uuid)
returns numeric
language sql stable security definer set search_path = ''
as $$
  select coalesce(sum(l.amount), 0) from public.plan_ledger l
  where l.plan_id = p_plan and l.entry_type in ('deposit', 'withdrawal', 'adjustment');
$$;

-- Assigned holdings at cost (the database has no live prices).
create function private.plan_assets_cost(p_plan uuid)
returns numeric
language sql stable security definer set search_path = ''
as $$
  select coalesce(sum(ph.quantity * h.buy_price), 0)
  from public.plan_holdings ph join public.holdings h on h.id = ph.holding_id
  where ph.plan_id = p_plan;
$$;

create function private.plan_saved(p_plan uuid)
returns numeric
language sql stable security definer set search_path = ''
as $$
  select private.plan_cash(p_plan) + private.plan_assets_cost(p_plan);
$$;

-- Same checks as before, but "saved" is cash plus assigned holdings at cost,
-- and this month's share counts net flow (assets assigned count as money put in).
create or replace function private.check_plan(p_plan uuid, p_daily boolean)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  p          public.plans;
  v_today    date := (now() at time zone 'Asia/Jakarta')::date;
  v_saved    numeric;
  v_left_amt numeric;
  v_pct      numeric;
  v_mile     int;
  v_total    int;
  v_elapsed  int;
  v_expected numeric;
  v_days     int;
  v_months   int;
  v_needed   numeric;
  v_thismon  numeric;
  v_link     text;
  v_name     text;
begin
  select * into p from public.plans where id = p_plan;
  if p.id is null or p.status in ('achieved', 'cancelled') then return; end if;
  v_link := 'plan:' || p.id;
  v_name := p.icon || ' ' || p.name;

  v_saved := private.plan_saved(p.id);
  v_left_amt := greatest(p.target_amount - v_saved, 0);
  v_pct := v_saved / p.target_amount * 100;

  -- milestones: only the highest one reached, once
  v_mile := case when v_pct >= 100 then 100 when v_pct >= 75 then 75 when v_pct >= 50 then 50
                 when v_pct >= 25 then 25 else 0 end;
  if v_mile = 100 then
    update public.plans set status = 'achieved' where id = p.id;
    perform private.notify(p.household_id, 'plan_achieved', p.id, '100',
      v_name || ' reached its target',
      private.rp(v_saved) || ' saved of ' || private.rp(p.target_amount) || '.', v_link);
    return;
  elsif v_mile > 0 then
    perform private.notify(p.household_id, 'plan_milestone', p.id, v_mile::text,
      v_name || ' is ' || v_mile || '% there',
      private.rp(v_saved) || ' saved of ' || private.rp(p.target_amount) || '.', v_link);
  end if;

  -- paused plans get no date-based reminders
  if not p_daily or p.status <> 'active' then return; end if;

  v_days   := p.target_date - v_today;
  v_months := greatest(1, (extract(year from age(p.target_date, v_today)) * 12
                           + extract(month from age(p.target_date, v_today))
                           + case when extract(day from age(p.target_date, v_today)) > 0 then 1 else 0 end)::int);
  v_needed := v_left_amt / v_months;

  -- keys carry the target date, so moving the date re-arms these
  if v_days < 0 then
    perform private.notify(p.household_id, 'plan_overdue', p.id, 'overdue:' || p.target_date,
      v_name || ' passed its target date',
      private.rp(v_left_amt) || ' still to go. Move the date or add money.', v_link);
    return;
  end if;

  if v_days <= 7 then
    perform private.notify(p.household_id, 'plan_deadline', p.id, '7d:' || p.target_date,
      v_name || ': ' || case when v_days = 0 then 'due today'
                             else v_days || ' day' || case when v_days = 1 then '' else 's' end || ' left' end,
      private.rp(v_left_amt) || ' still to go.', v_link);
  elsif v_days <= 30 then
    perform private.notify(p.household_id, 'plan_deadline', p.id, '30d:' || p.target_date,
      v_name || ': ' || v_days || ' days left',
      private.rp(v_left_amt) || ' still to go.', v_link);
  end if;

  -- behind: below the straight line from start to target by more than 5% of
  -- the target (FR-PLN-05). One notification each time the plan falls behind.
  v_total    := greatest(p.target_date - p.start_date, 1);
  v_elapsed  := least(greatest(v_today - p.start_date, 0), v_total);
  v_expected := p.target_amount * v_elapsed / v_total;
  if v_saved < v_expected - p.target_amount * 0.05 then
    if p.behind_since is null then
      update public.plans set behind_since = v_today where id = p.id;
      perform private.notify(p.household_id, 'plan_behind', p.id, v_today::text,
        v_name || ' is falling behind',
        'Saved ' || private.rp(v_saved) || '; by now it should be about '
          || private.rp(v_expected) || '. Aim for ' || private.rp(v_needed) || ' a month.', v_link);
    end if;
  elsif p.behind_since is not null then
    update public.plans set behind_since = null where id = p.id;
  end if;

  -- monthly reminder from the 25th, if this month's share is not in yet
  if extract(day from v_today) >= 25 then
    select coalesce(sum(case when l.entry_type = 'asset_out' then -l.amount else l.amount end), 0)
    into v_thismon from public.plan_ledger l
    where l.plan_id = p.id and l.date >= date_trunc('month', v_today)::date;
    if v_needed - v_thismon > 0 then
      perform private.notify(p.household_id, 'plan_monthly', p.id, to_char(v_today, 'YYYY-MM'),
        v_name || ': ' || private.rp(v_needed - v_thismon) || ' to go this month',
        'Putting in ' || private.rp(v_needed) || ' a month reaches ' || private.rp(p.target_amount)
          || ' by ' || private.long_date(p.target_date) || '.', v_link);
    end if;
  end if;
end;
$$;

-- Per plan, for the closing statement. Cash is split into opening, deposits,
-- withdrawals, adjustments and closing; assigned holdings are rebuilt from the
-- ledger as of month end and valued at the saved month-end price, or at the
-- last recorded price when none was saved (assets_priced says which).
-- Old keys (contributed, saved, progress) keep their meaning.
create or replace function private.plan_figures(p_household uuid, p_month date)
returns jsonb
language sql stable security definer set search_path = ''
as $$
  with b as (
    select date_trunc('month', p_month)::date as m0,
           (date_trunc('month', p_month) + interval '1 month')::date as m1
  ),
  cash as (
    select l.plan_id,
      coalesce(sum(l.amount) filter (where l.entry_type in ('deposit', 'withdrawal', 'adjustment')
                                       and l.date < b.m0), 0) as opening_cash,
      coalesce(sum(l.amount) filter (where l.entry_type = 'deposit' and l.date >= b.m0), 0) as deposits,
      coalesce(-sum(l.amount) filter (where l.entry_type = 'withdrawal' and l.date >= b.m0), 0) as withdrawals,
      coalesce(sum(l.amount) filter (where l.entry_type = 'adjustment' and l.date >= b.m0), 0) as adjustments,
      coalesce(sum(l.amount) filter (where l.entry_type in ('deposit', 'withdrawal', 'adjustment')), 0) as closing_cash,
      count(*) filter (where l.date >= b.m0) as entries
    from public.plan_ledger l cross join b
    where l.household_id = p_household and l.date < b.m1
    group by l.plan_id
  ),
  held as (
    select l.plan_id, l.asset_type, upper(trim(l.ticker)) as t, lower(trim(l.asset_name)) as n,
      sum(case when l.entry_type = 'asset_in' then l.quantity else -l.quantity end) as qty,
      (array_agg(l.unit_price order by l.date desc, l.created_at desc))[1] as last_price
    from public.plan_ledger l cross join b
    where l.household_id = p_household and l.date < b.m1 and l.entry_type in ('asset_in', 'asset_out')
    group by l.plan_id, l.asset_type, upper(trim(l.ticker)), lower(trim(l.asset_name))
    having sum(case when l.entry_type = 'asset_in' then l.quantity else -l.quantity end) > 0
  ),
  valued as (
    select h.plan_id, h.qty * coalesce(mp.price, h.last_price) as value, (mp.price is not null) as market
    from held h cross join b
    left join public.month_end_prices mp
      on mp.household_id = p_household and mp.month = b.m0
     and mp.asset_type = h.asset_type and mp.ticker = h.t and mp.name = h.n
  ),
  assets as (
    select v.plan_id, sum(v.value) as asset_value, bool_and(v.market) as all_market
    from valued v group by v.plan_id
  ),
  f as (
    select p.id, p.name, p.icon, p.status, p.target_amount, p.target_date,
      coalesce(c.opening_cash, 0) as opening_cash, coalesce(c.deposits, 0) as deposits,
      coalesce(c.withdrawals, 0) as withdrawals, coalesce(c.adjustments, 0) as adjustments,
      coalesce(c.closing_cash, 0) as closing_cash,
      coalesce(a.asset_value, 0) as asset_value, a.all_market
    from public.plans p
    cross join b
    left join cash c on c.plan_id = p.id
    left join assets a on a.plan_id = p.id
    where p.household_id = p_household and p.start_date < b.m1
      and (coalesce(c.entries, 0) > 0
           or p.status in ('active', 'paused')
           or (p.status = 'achieved' and p.achieved_at >= b.m1))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'plan_id', id, 'name', name, 'icon', icon, 'status', status,
    'target', target_amount, 'target_date', target_date,
    'opening_cash', opening_cash, 'deposits', deposits, 'withdrawals', withdrawals,
    'adjustments', adjustments, 'cash', closing_cash,
    'asset_value', asset_value,
    'assets_priced', case when all_market is null then null when all_market then 'market' else 'cost' end,
    'contributed', deposits,
    'saved', closing_cash + asset_value,
    'progress', round(greatest(least((closing_cash + asset_value) / target_amount * 100, 100), 0), 1)
  ) order by target_date, name), '[]')
  from f;
$$;

-- ---------------------------------------------------------------
-- Views for the app
-- ---------------------------------------------------------------

-- Old name, old shape: the deposit rows. Lets the current app keep working.
create view public.plan_contributions with (security_invoker = true) as
  select id, household_id, plan_id, date, amount, note, transaction_id, created_by, created_at
  from public.plan_ledger
  where entry_type = 'deposit'
  with check option;

-- The ledger with a running balance per plan: cash alone, and cash plus
-- assigned holdings at the price they were recorded at.
create view public.plan_ledger_running with (security_invoker = true) as
  select l.*,
    sum(case when l.entry_type in ('deposit', 'withdrawal', 'adjustment') then l.amount else 0 end)
      over (partition by l.plan_id order by l.date, l.created_at, l.id) as cash_balance,
    sum(case when l.entry_type = 'asset_out' then -l.amount else l.amount end)
      over (partition by l.plan_id order by l.date, l.created_at, l.id) as value_balance
  from public.plan_ledger l;

revoke all on public.plan_contributions, public.plan_ledger_running from anon;
grant select, insert, update, delete on public.plan_contributions to authenticated;
grant select on public.plan_ledger_running to authenticated;
grant all on public.plan_contributions, public.plan_ledger_running to service_role;

-- ---------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------

-- Earmark a quantity of a lot for a plan. p_price is the price to record
-- (the app passes the live one); it defaults to the lot's cost.
create function public.assign_holding_to_plan(
  p_plan     uuid,
  p_holding  uuid,
  p_quantity numeric,
  p_price    numeric default null,
  p_date     date default null
)
returns public.plan_ledger
language plpgsql security definer set search_path = ''
as $$
declare
  v_plan  public.plans;
  v_hold  public.holdings;
  v_price numeric;
  v_row   public.plan_ledger;
begin
  select * into v_plan from public.plans where id = p_plan;
  if v_plan.id is null or not private.is_member(v_plan.household_id) then
    raise exception 'Plan not found';
  end if;
  if v_plan.status = 'cancelled' then
    raise exception 'This plan is cancelled. Resume it first.';
  end if;
  select * into v_hold from public.holdings where id = p_holding and household_id = v_plan.household_id;
  if v_hold.id is null then
    raise exception 'Holding not found';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Quantity must be positive';
  end if;
  v_price := coalesce(p_price, v_hold.buy_price);
  if v_price < 0 then
    raise exception 'Price cannot be negative';
  end if;

  insert into public.plan_holdings (household_id, plan_id, holding_id, quantity)
  values (v_plan.household_id, p_plan, p_holding, p_quantity)
  on conflict (plan_id, holding_id) do update set quantity = public.plan_holdings.quantity + excluded.quantity;

  insert into public.plan_ledger
    (household_id, plan_id, date, amount, note, entry_type, holding_id,
     asset_type, ticker, asset_name, quantity, unit_price)
  values
    (v_plan.household_id, p_plan, coalesce(p_date, (now() at time zone 'Asia/Jakarta')::date),
     round(p_quantity * v_price, 2), '', 'asset_in', p_holding,
     v_hold.asset_type, v_hold.ticker, v_hold.name, p_quantity, v_price)
  returning * into v_row;
  return v_row;
end;
$$;

-- Take a quantity of a lot back out of a plan (all of it when p_quantity is null).
create function public.unassign_holding_from_plan(
  p_plan     uuid,
  p_holding  uuid,
  p_quantity numeric default null,
  p_price    numeric default null,
  p_date     date default null
)
returns public.plan_ledger
language plpgsql security definer set search_path = ''
as $$
declare
  v_plan  public.plans;
  v_hold  public.holdings;
  v_ph    public.plan_holdings;
  v_qty   numeric;
  v_price numeric;
  v_row   public.plan_ledger;
begin
  select * into v_plan from public.plans where id = p_plan;
  if v_plan.id is null or not private.is_member(v_plan.household_id) then
    raise exception 'Plan not found';
  end if;
  select * into v_ph from public.plan_holdings where plan_id = p_plan and holding_id = p_holding for update;
  if v_ph.id is null then
    raise exception 'That holding is not assigned to this plan';
  end if;
  select * into v_hold from public.holdings where id = p_holding;
  v_qty := coalesce(p_quantity, v_ph.quantity);
  if v_qty <= 0 or v_qty > v_ph.quantity then
    raise exception 'Only % is assigned to this plan', v_ph.quantity;
  end if;
  v_price := coalesce(p_price, v_hold.buy_price);
  if v_price < 0 then
    raise exception 'Price cannot be negative';
  end if;

  if v_qty >= v_ph.quantity then
    delete from public.plan_holdings where id = v_ph.id;
  else
    update public.plan_holdings set quantity = quantity - v_qty where id = v_ph.id;
  end if;

  insert into public.plan_ledger
    (household_id, plan_id, date, amount, note, entry_type, holding_id,
     asset_type, ticker, asset_name, quantity, unit_price)
  values
    (v_plan.household_id, p_plan, coalesce(p_date, (now() at time zone 'Asia/Jakarta')::date),
     round(v_qty * v_price, 2), '', 'asset_out', p_holding,
     v_hold.asset_type, v_hold.ticker, v_hold.name, v_qty, v_price)
  returning * into v_row;
  return v_row;
end;
$$;

-- Cash earmarked per account: the cash in every plan that is not cancelled.
-- Free to spend = account balance minus this. Assets are not cash accounts,
-- so they are not counted here.
create function public.account_earmarks(p_household uuid)
returns table (account_id uuid, earmarked numeric)
language sql stable security definer set search_path = ''
as $$
  select p.account_id, coalesce(sum(l.amount), 0)
  from public.plans p
  join public.plan_ledger l on l.plan_id = p.id and l.entry_type in ('deposit', 'withdrawal', 'adjustment')
  where p.household_id = p_household and p.status <> 'cancelled' and p.account_id is not null
    and private.is_member(p_household)
  group by p.account_id;
$$;

-- Owners save the month-end market price of each asset before closing, so the
-- statement values assigned holdings at market. p_prices is a JSON array of
-- {asset_type, ticker, name, price}. Closed months cannot be changed.
create function public.set_month_end_prices(p_household uuid, p_month date, p_prices jsonb)
returns int
language plpgsql security definer set search_path = ''
as $$
declare
  v_month date := date_trunc('month', p_month)::date;
  v_lock  date := private.locked_through(p_household);
  v_n     int;
begin
  if not private.is_owner(p_household) then
    raise exception 'Only an owner can set month-end prices';
  end if;
  if v_lock is not null and v_month <= v_lock then
    raise exception 'That month is already closed';
  end if;
  if jsonb_typeof(p_prices) <> 'array' then
    raise exception 'Prices must be a list';
  end if;
  insert into public.month_end_prices (household_id, month, asset_type, ticker, name, price)
  select p_household, v_month, x.asset_type, upper(trim(coalesce(x.ticker, ''))),
         lower(trim(coalesce(x.name, ''))), x.price
  from jsonb_to_recordset(p_prices) as x(asset_type text, ticker text, name text, price numeric)
  where x.price > 0 and x.asset_type in ('gold', 'stock')
  on conflict (household_id, month, asset_type, ticker, name) do update set price = excluded.price;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

revoke all on function private.guard_plan_cash() from public;
revoke all on function private.plan_holding_rules() from public;
revoke all on function private.release_plan_holdings() from public;
revoke all on function private.plan_cash(uuid) from public;
revoke all on function private.plan_assets_cost(uuid) from public;
revoke all on function private.plan_saved(uuid) from public;
revoke all on function public.assign_holding_to_plan(uuid, uuid, numeric, numeric, date) from public, anon;
revoke all on function public.unassign_holding_from_plan(uuid, uuid, numeric, numeric, date) from public, anon;
revoke all on function public.account_earmarks(uuid) from public, anon;
revoke all on function public.set_month_end_prices(uuid, date, jsonb) from public, anon;
grant execute on function public.assign_holding_to_plan(uuid, uuid, numeric, numeric, date) to authenticated;
grant execute on function public.unassign_holding_from_plan(uuid, uuid, numeric, numeric, date) to authenticated;
grant execute on function public.account_earmarks(uuid) to authenticated;
grant execute on function public.set_month_end_prices(uuid, date, jsonb) to authenticated;

-- ====================================================================
-- 20261120000000_plan_sale_and_month_end.sql
-- ====================================================================

-- Plan decisions, round 2.
--
-- 1. Selling gold or stocks that sit in a plan puts the sale proceeds into that
--    plan's cash (a deposit entry, "Sale proceeds: ...") on top of releasing the
--    holding (asset_out). Deleting a holding without selling it adds no cash.
--    sell_holding tells the release trigger the sell price through the
--    transaction-local setting ft.sale_price. Cancelled plans are skipped.
-- 2. Month-end prices record the date they are for (price_date), and the
--    statement says so (plans[].prices_on). The app fetches the price of the
--    last day of the month (the last trading day on or before it).
--
-- Needs 20261119000000_plan_ledger.sql.

alter table public.month_end_prices add column price_date date;

-- Release trigger function (now with sale proceeds)
create or replace function private.release_plan_holdings()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_keep   numeric := case when tg_op = 'DELETE' then 0 else new.quantity end;
  v_total  numeric;
  v_extra  numeric;
  v_take   numeric;
  v_today  date := (now() at time zone 'Asia/Jakarta')::date;
  v_sale   numeric := nullif(current_setting('ft.sale_price', true), '')::numeric; -- set by sell_holding
  v_status text;
  v_lock   date;
  v_date   date;
  r        record;
begin
  if tg_op = 'UPDATE' and new.quantity >= old.quantity then
    return new;
  end if;
  if exists (select 1 from public.households h where h.id = old.household_id) then
    select coalesce(sum(ph.quantity), 0) into v_total from public.plan_holdings ph where ph.holding_id = old.id;
    v_extra := v_total - v_keep;
    if v_extra > 0 then
      v_lock := private.locked_through(old.household_id);
      v_date := greatest(v_today, coalesce(v_lock + 1, v_today));
      for r in
        select ph.id, ph.plan_id, ph.quantity from public.plan_holdings ph
        where ph.holding_id = old.id order by ph.created_at desc, ph.id
      loop
        exit when v_extra <= 0;
        v_take := least(r.quantity, v_extra);
        if v_take >= r.quantity then
          delete from public.plan_holdings where id = r.id;
        else
          update public.plan_holdings set quantity = quantity - v_take where id = r.id;
        end if;
        insert into public.plan_ledger
          (household_id, plan_id, date, amount, note, entry_type, holding_id,
           asset_type, ticker, asset_name, quantity, unit_price)
        values
          (old.household_id, r.plan_id, v_date, round(v_take * old.buy_price, 2), 'Holding sold or removed',
           'asset_out', old.id, old.asset_type, old.ticker, old.name, v_take, old.buy_price);
        -- a sale (not a plain delete) puts its proceeds into the plan's cash
        if v_sale is not null and v_sale > 0 then
          select p.status into v_status from public.plans p where p.id = r.plan_id;
          if v_status is distinct from 'cancelled' then
            insert into public.plan_ledger
              (household_id, plan_id, date, amount, note, entry_type)
            values
              (old.household_id, r.plan_id, v_date, round(v_take * v_sale, 2),
               'Sale proceeds: ' || coalesce(nullif(old.name, ''), nullif(old.ticker, ''), old.asset_type), 'deposit');
          end if;
        end if;
        v_extra := v_extra - v_take;
      end loop;
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

-- sell_holding (now sets ft.sale_price)
create or replace function public.sell_holding(
  p_household  uuid,
  p_quantity   numeric,
  p_sell_price numeric,
  p_account    uuid default null,
  p_holding    uuid default null,
  p_ticker     text default null,
  p_name       text default null,
  p_date       date default null,
  p_source     text default 'web'
)
returns public.sales
language plpgsql security invoker set search_path = ''
as $$
declare
  v_date      date := coalesce(p_date, (now() at time zone 'Asia/Jakarta')::date);
  v_ticker    text := upper(trim(coalesce(p_ticker, '')));
  v_name      text := lower(trim(coalesce(p_name, '')));
  v_remaining numeric := p_quantity;
  v_available numeric := 0;
  v_cost      numeric := 0;
  v_take      numeric;
  v_type      text;
  v_lot_tick  text;
  v_lot_name  text;
  v_label     text;
  v_proceeds  numeric;
  v_cat       uuid;
  v_lot       record;
  v_sale      public.sales;
begin
  if p_quantity is null or p_quantity <= 0 or p_sell_price is null or p_sell_price <= 0 then
    raise exception 'Quantity and sell price must be positive';
  end if;
  if p_holding is null and v_ticker = '' and v_name = '' then
    raise exception 'Say which holding to sell';
  end if;

  -- tell the plan-release trigger the sell price, so proceeds reach the plans (this transaction only)
  perform set_config('ft.sale_price', p_sell_price::text, true);

  for v_lot in
    select h.* from public.holdings h
    where h.household_id = p_household
      and (
        (p_holding is not null and h.id = p_holding)
        or (p_holding is null
            and (v_ticker = '' or upper(trim(h.ticker)) = v_ticker)
            and (v_name   = '' or lower(trim(h.name))   = v_name))
      )
    order by h.created_at, h.id
    for update
  loop
    v_available := v_available + v_lot.quantity;
    v_type := v_lot.asset_type; v_lot_tick := v_lot.ticker; v_lot_name := v_lot.name;

    if v_remaining > 0 then
      v_take := least(v_lot.quantity, v_remaining);
      v_cost := v_cost + v_take * v_lot.buy_price;
      v_remaining := v_remaining - v_take;
      if v_lot.quantity - v_take <= 0 then
        delete from public.holdings where id = v_lot.id;
      else
        update public.holdings set quantity = quantity - v_take where id = v_lot.id;
      end if;
    end if;
  end loop;

  perform set_config('ft.sale_price', '', true);

  if v_type is null then
    raise exception 'No matching holding found';
  end if;
  if v_remaining > 0 then
    -- raising rolls back the draw-down above
    raise exception 'Selling % but only % held', p_quantity, v_available;
  end if;

  v_proceeds := p_quantity * p_sell_price;
  v_label := coalesce(nullif(v_lot_name, ''), nullif(v_lot_tick, ''), v_type);

  select id into v_cat from public.categories
  where household_id = p_household and lower(name) = 'asset sale';
  if v_cat is null then
    insert into public.categories (household_id, name)
    values (p_household, 'Asset Sale') returning id into v_cat;
  end if;

  insert into public.transactions
    (household_id, date, type, category_id, description, amount, source, account_id)
  values
    (p_household, v_date, 'income', v_cat,
     'Sold ' || p_quantity || ' ' || v_label || ' @ ' || p_sell_price ||
       case when v_proceeds - v_cost >= 0 then ' (gain)' else ' (loss)' end,
     v_proceeds, p_source, p_account);

  insert into public.sales
    (household_id, date, asset_type, ticker, name, quantity, avg_buy_price,
     sell_price, proceeds, cost_basis, realized_pl, account_id)
  values
    (p_household, v_date, v_type, v_lot_tick, v_lot_name, p_quantity, v_cost / p_quantity,
     p_sell_price, v_proceeds, v_cost, v_proceeds - v_cost, p_account)
  returning * into v_sale;

  return v_sale;
end;
$$;

-- Plan figures (now with prices_on)
create or replace function private.plan_figures(p_household uuid, p_month date)
returns jsonb
language sql stable security definer set search_path = ''
as $$
  with b as (
    select date_trunc('month', p_month)::date as m0,
           (date_trunc('month', p_month) + interval '1 month')::date as m1
  ),
  cash as (
    select l.plan_id,
      coalesce(sum(l.amount) filter (where l.entry_type in ('deposit', 'withdrawal', 'adjustment')
                                       and l.date < b.m0), 0) as opening_cash,
      coalesce(sum(l.amount) filter (where l.entry_type = 'deposit' and l.date >= b.m0), 0) as deposits,
      coalesce(-sum(l.amount) filter (where l.entry_type = 'withdrawal' and l.date >= b.m0), 0) as withdrawals,
      coalesce(sum(l.amount) filter (where l.entry_type = 'adjustment' and l.date >= b.m0), 0) as adjustments,
      coalesce(sum(l.amount) filter (where l.entry_type in ('deposit', 'withdrawal', 'adjustment')), 0) as closing_cash,
      count(*) filter (where l.date >= b.m0) as entries
    from public.plan_ledger l cross join b
    where l.household_id = p_household and l.date < b.m1
    group by l.plan_id
  ),
  held as (
    select l.plan_id, l.asset_type, upper(trim(l.ticker)) as t, lower(trim(l.asset_name)) as n,
      sum(case when l.entry_type = 'asset_in' then l.quantity else -l.quantity end) as qty,
      (array_agg(l.unit_price order by l.date desc, l.created_at desc))[1] as last_price
    from public.plan_ledger l cross join b
    where l.household_id = p_household and l.date < b.m1 and l.entry_type in ('asset_in', 'asset_out')
    group by l.plan_id, l.asset_type, upper(trim(l.ticker)), lower(trim(l.asset_name))
    having sum(case when l.entry_type = 'asset_in' then l.quantity else -l.quantity end) > 0
  ),
  valued as (
    select h.plan_id, h.qty * coalesce(mp.price, h.last_price) as value, (mp.price is not null) as market, mp.price_date as pdate
    from held h cross join b
    left join public.month_end_prices mp
      on mp.household_id = p_household and mp.month = b.m0
     and mp.asset_type = h.asset_type and mp.ticker = h.t and mp.name = h.n
  ),
  assets as (
    select v.plan_id, sum(v.value) as asset_value, bool_and(v.market) as all_market,
           min(v.pdate) as prices_on
    from valued v group by v.plan_id
  ),
  f as (
    select p.id, p.name, p.icon, p.status, p.target_amount, p.target_date,
      coalesce(c.opening_cash, 0) as opening_cash, coalesce(c.deposits, 0) as deposits,
      coalesce(c.withdrawals, 0) as withdrawals, coalesce(c.adjustments, 0) as adjustments,
      coalesce(c.closing_cash, 0) as closing_cash,
      coalesce(a.asset_value, 0) as asset_value, a.all_market, a.prices_on
    from public.plans p
    cross join b
    left join cash c on c.plan_id = p.id
    left join assets a on a.plan_id = p.id
    where p.household_id = p_household and p.start_date < b.m1
      and (coalesce(c.entries, 0) > 0
           or p.status in ('active', 'paused')
           or (p.status = 'achieved' and p.achieved_at >= b.m1))
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'plan_id', id, 'name', name, 'icon', icon, 'status', status,
    'target', target_amount, 'target_date', target_date,
    'opening_cash', opening_cash, 'deposits', deposits, 'withdrawals', withdrawals,
    'adjustments', adjustments, 'cash', closing_cash,
    'asset_value', asset_value,
    'prices_on', prices_on,
    'assets_priced', case when all_market is null then null when all_market then 'market' else 'cost' end,
    'contributed', deposits,
    'saved', closing_cash + asset_value,
    'progress', round(greatest(least((closing_cash + asset_value) / target_amount * 100, 100), 0), 1)
  ) order by target_date, name), '[]')
  from f;
$$;

-- set_month_end_prices (now takes price_date per row)
create or replace function public.set_month_end_prices(p_household uuid, p_month date, p_prices jsonb)
returns int
language plpgsql security definer set search_path = ''
as $$
declare
  v_month date := date_trunc('month', p_month)::date;
  v_lock  date := private.locked_through(p_household);
  v_n     int;
begin
  if not private.is_owner(p_household) then
    raise exception 'Only an owner can set month-end prices';
  end if;
  if v_lock is not null and v_month <= v_lock then
    raise exception 'That month is already closed';
  end if;
  if jsonb_typeof(p_prices) <> 'array' then
    raise exception 'Prices must be a list';
  end if;
  insert into public.month_end_prices (household_id, month, asset_type, ticker, name, price, price_date)
  select p_household, v_month, x.asset_type, upper(trim(coalesce(x.ticker, ''))),
         lower(trim(coalesce(x.name, ''))), x.price,
         coalesce(x.price_date, (now() at time zone 'Asia/Jakarta')::date)
  from jsonb_to_recordset(p_prices) as x(asset_type text, ticker text, name text, price numeric, price_date date)
  where x.price > 0 and x.asset_type in ('gold', 'stock')
  on conflict (household_id, month, asset_type, ticker, name) do update set price = excluded.price, price_date = excluded.price_date;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;

-- ====================================================================
-- 20261121000000_scheduled_jobs.sql
-- ====================================================================

-- Scheduled jobs (all times WIB; pg_cron runs in UTC).
--
--   08:00, 12:00, 16:00  notification checks (public.run_notifications())
--
-- The checks that used to run at 07:00 and 19:00 move to the three times above, and the
-- last-day month-close reminder (FR-CLS-12) now starts at 16:00 instead of 19:00.
-- This needs the pg_cron extension. Without it the schedule is skipped with a notice;
-- the app still runs the notification checks when it opens.
-- (Holding prices are not scheduled: the Portfolio page has a Sync prices button.)
--
-- Needs 20261118000000_plans.sql.

-- The month-close reminder on the last day of a month used to start at 19:00 WIB. The last
-- check of the day now runs at 16:00, so the reminder starts at 16:00.
create or replace function private.check_household(p_household uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  v_plan   uuid;
  v_now    timestamp := now() at time zone 'Asia/Jakarta';
  v_today  date := v_now::date;
  v_this   date := date_trunc('month', v_now)::date;
  v_lock   date := private.locked_through(p_household);
  v_next   date;
  v_day    int := extract(day from v_now)::int;
  v_last   boolean := (v_today + 1) = (v_this + interval '1 month')::date;
begin
  for v_plan in select id from public.plans where household_id = p_household and status in ('active', 'paused') loop
    perform private.check_plan(v_plan, true);
  end loop;

  -- the month that should be closed next; none until the ledger has entries
  if v_lock is not null then
    v_next := v_lock + 1;
  elsif exists (select 1 from public.transactions t where t.household_id = p_household and t.date < v_this) then
    v_next := (v_this - interval '1 month')::date;
  end if;

  -- last day of a month, when it is the next one to close
  if v_last and extract(hour from v_now) >= 16
     and (v_lock + 1 = v_this
          or (v_lock is null and v_next is null
              and exists (select 1 from public.transactions t where t.household_id = p_household))) then
    perform private.notify(p_household, 'month_close', null, to_char(v_this, 'YYYY-MM') || '-last',
      'Time to close ' || private.month_name(v_this),
      'The month ends today. Close it from tomorrow once the last entries are in.',
      'statement:' || to_char(v_this, 'YYYY-MM-DD'));
  end if;

  -- only the latest reminder that applies, so a late first run sends one, not three
  if v_next is not null and v_next < v_this then
    if v_day >= 7 then
      perform private.notify(p_household, 'month_close', null, to_char(v_next, 'YYYY-MM') || '-d7',
        'Last reminder: close ' || private.month_name(v_next),
        'It has been a week since the month ended.', 'statement:' || to_char(v_next, 'YYYY-MM-DD'));
    elsif v_day >= 3 then
      perform private.notify(p_household, 'month_close', null, to_char(v_next, 'YYYY-MM') || '-d3',
        private.month_name(v_next) || ' is still open',
        'Close it so its statement is saved and its entries are locked.', 'statement:' || to_char(v_next, 'YYYY-MM-DD'));
    else
      perform private.notify(p_household, 'month_close', null, to_char(v_next, 'YYYY-MM') || '-d1',
        'Close ' || private.month_name(v_next),
        'Check the figures and bank balances, then lock the month.', 'statement:' || to_char(v_next, 'YYYY-MM-DD'));
    end if;
  end if;
end;
$$;

-- Notification checks: 01:00, 05:00 and 09:00 UTC = 08:00, 12:00 and 16:00 WIB.
do $$
begin
  create extension if not exists pg_cron with schema pg_catalog;
  perform cron.unschedule(jobid) from cron.job
    where jobname in ('finance-notifications-morning', 'finance-notifications-evening', 'finance-notifications');
  perform cron.schedule('finance-notifications', '0 1,5,9 * * *', 'select public.run_notifications()');
exception when others then
  raise notice 'pg_cron is not set up (%). Notification checks are not scheduled.', sqlerrm;
end;
$$;

-- ====================================================================
-- 20261122000000_loans.sql
-- ====================================================================

-- V2.9: loans from the household's own accounts.
-- A loan is money taken out of one account (for example Bersama) and lent to a
-- household member, who pays it back into an account. The disbursement is a
-- `loan-out` transaction (balance goes down) and each repayment a `loan-in`
-- transaction (balance goes up). Neither counts as income or expense. The monthly
-- statement lists the loans still unpaid at month end and stores that list when
-- the month closes.
-- Needs 20261117 (ledger closing) and 20261118 (notifications).
-- Run this once in the SQL Editor (or with `supabase db push`).

-- ---------------------------------------------------------------
-- Table
-- ---------------------------------------------------------------
create table public.loans (
  id           uuid primary key default gen_random_uuid(),
  household_id uuid not null references public.households (id) on delete cascade,
  borrower_id  uuid references auth.users (id) on delete set null,  -- the household member who owes it
  amount       numeric(18, 2) not null check (amount > 0),
  date         date not null default ((now() at time zone 'Asia/Jakarta')::date),
  due_date     date,
  note         text not null default '',
  status       text not null default 'open' check (status in ('open', 'paid')),
  account_id   uuid references public.accounts (id) on delete set null,
  created_by   uuid references auth.users (id) on delete set null default auth.uid(),
  created_at   timestamptz not null default now(),
  check (due_date is null or due_date >= date)
);
create index loans_household_idx on public.loans (household_id, status, date desc);

alter table public.loans enable row level security;
create policy loans_select on public.loans
  for select to authenticated using (private.is_member(household_id));
-- Members read; only the RPCs below write.
revoke all on public.loans from anon, authenticated;
grant select on public.loans to authenticated;
grant all on public.loans to service_role;

-- ---------------------------------------------------------------
-- Transactions: two new types, linked to a loan
-- ---------------------------------------------------------------
alter table public.transactions drop constraint transactions_type_check;
alter table public.transactions add constraint transactions_type_check
  check (type in ('income', 'expense', 'invest', 'transfer-out', 'transfer-in', 'loan-in', 'loan-out'));
-- no action (checked at the end of the statement) so deleting a household still cascades
alter table public.transactions add column loan_id uuid references public.loans (id);
alter table public.transactions add constraint transactions_loan_ck
  check ((type in ('loan-in', 'loan-out')) = (loan_id is not null));
create index transactions_loan_idx on public.transactions (loan_id) where loan_id is not null;

-- Account balances count a loan received as money in and a payment as money out.
create or replace view public.account_balances
with (security_invoker = true) as
select
  a.id as account_id,
  a.household_id,
  a.name,
  a.archived,
  a.sort_order,
  a.opening_balance + coalesce(sum(
    case when t.type in ('income', 'transfer-in', 'loan-in') then t.amount else -t.amount end
  ), 0) as balance
from public.accounts a
left join public.transactions t on t.account_id = a.id
group by a.id;

-- Loan transactions are written only by the loan functions below (FR-LON-05).
create function private.guard_loan_txn()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_row public.transactions := case when tg_op = 'DELETE' then old else new end;
begin
  if coalesce(current_setting('ft.loan', true), '') = '1' then
    return v_row;
  end if;
  if tg_op = 'DELETE' then
    -- deleting the whole household still passes
    if v_row.type in ('loan-in', 'loan-out')
       and exists (select 1 from public.households h where h.id = v_row.household_id) then
      raise exception 'Loan entries are changed from the Loans screen';
    end if;
    return old;
  end if;
  if tg_op = 'INSERT' then
    if new.type in ('loan-in', 'loan-out') then
      raise exception 'Loan entries are added from the Loans screen';
    end if;
    return new;
  end if;
  -- UPDATE: no moving into or out of the loan types; only the "set null" of a deleted account passes
  if new.type in ('loan-in', 'loan-out') or old.type in ('loan-in', 'loan-out') then
    if to_jsonb(new) - 'account_id' = to_jsonb(old) - 'account_id' and new.account_id is null then
      return new;
    end if;
    raise exception 'Loan entries are changed from the Loans screen';
  end if;
  return new;
end;
$$;

create trigger transactions_loan_guard
  before insert or update or delete on public.transactions
  for each row execute function private.guard_loan_txn();

-- ---------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------
create function private.loan_repaid(p_loan uuid)
returns numeric
language sql stable security definer set search_path = ''
as $$
  select coalesce(sum(amount), 0) from public.transactions where loan_id = p_loan and type = 'loan-in';
$$;

-- Status follows the payments: open while something is outstanding, else paid.
create function private.refresh_loan(p_loan uuid)
returns void
language sql security definer set search_path = ''
as $$
  update public.loans l
  set status = case when l.amount - private.loan_repaid(l.id) <= 0 then 'paid' else 'open' end
  where l.id = p_loan;
$$;

-- Loans still unpaid at the end of the month, as a JSON array (FR-CLS-16).
create function private.loan_figures(p_household uuid, p_month date)
returns jsonb
language sql stable security definer set search_path = ''
as $$
  with b as (
    select date_trunc('month', p_month)::date as m0,
           (date_trunc('month', p_month) + interval '1 month')::date as m1
  ),
  f as (
    select l.id, l.borrower_id, u.email as borrower_email, l.amount, l.date, l.due_date, l.note,
      case when l.date >= b.m0 then l.amount else 0 end as borrowed,
      coalesce(sum(t.amount) filter (where t.date >= b.m0), 0) as repaid_month,
      coalesce(sum(t.amount), 0) as repaid_to_date
    from public.loans l
    cross join b
    left join auth.users u on u.id = l.borrower_id
    left join public.transactions t on t.loan_id = l.id and t.type = 'loan-in' and t.date < b.m1
    where l.household_id = p_household and l.date < b.m1
    group by l.id, u.email, b.m0, b.m1
    having l.amount - coalesce(sum(t.amount), 0) > 0
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'loan_id', id, 'borrower_id', borrower_id, 'borrower', borrower_email,
    'amount', amount, 'date', date, 'due_date', due_date, 'note', note,
    'borrowed', borrowed, 'repaid_month', repaid_month, 'repaid_to_date', repaid_to_date,
    'outstanding', amount - repaid_to_date
  ) order by date, id), '[]')
  from f;
$$;

-- ---------------------------------------------------------------
-- Statement figures: loans join the account maths (FR-CLS-15 / 16)
-- ---------------------------------------------------------------
-- Same body as in 20261117, with loan-in and loan-out added. The plans migration
-- wraps this function (period_figures), so replacing it here is enough.
create or replace function private.period_figures_base(p_household uuid, p_month date)
returns jsonb
language plpgsql stable security definer set search_path = ''
as $$
declare
  m0 date := date_trunc('month', p_month)::date;
  m1 date := (date_trunc('month', p_month) + interval '1 month')::date;
  v_accounts jsonb;
  v_totals   jsonb;
  v_cats     jsonb;
  v_realized numeric;
  v_check    jsonb;
  v_income   numeric;
  v_expense  numeric;
  v_invest   numeric;
begin
  with acc_rows as (
    select a.id as account_id, a.name, a.sort_order, a.archived, a.opening_balance as base
    from public.accounts a where a.household_id = p_household
    union all
    select null, 'Unassigned', 1000000, false, 0
    where exists (select 1 from public.transactions t
                  where t.household_id = p_household and t.account_id is null and t.date < m1)
  ),
  figs as (
    select r.account_id, r.name, r.sort_order, r.archived,
      r.base + coalesce(sum(case when t.date < m0 then
        case when t.type in ('income', 'transfer-in', 'loan-in') then t.amount else -t.amount end end), 0) as opening,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'income'), 0)       as income,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'expense'), 0)      as expense,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'invest'), 0)       as invest,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'transfer-in'), 0)  as transfer_in,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'transfer-out'), 0) as transfer_out,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'loan-in'), 0)      as loan_in,
      coalesce(sum(t.amount) filter (where t.date >= m0 and t.type = 'loan-out'), 0)     as loan_out
    from acc_rows r
    left join public.transactions t
      on t.household_id = p_household and t.date < m1
     and t.account_id is not distinct from r.account_id
    group by r.account_id, r.name, r.sort_order, r.archived, r.base
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'account_id', account_id, 'name', name, 'sort_order', sort_order, 'archived', archived,
      'opening', opening, 'income', income, 'expense', expense, 'invest', invest,
      'transfer_in', transfer_in, 'transfer_out', transfer_out,
      'loan_in', loan_in, 'loan_out', loan_out,
      'closing', opening + income + transfer_in + loan_in - expense - invest - transfer_out - loan_out
    ) order by sort_order, name), '[]'),
    jsonb_build_object(
      'opening', coalesce(sum(opening), 0), 'income', coalesce(sum(income), 0),
      'expense', coalesce(sum(expense), 0), 'invest', coalesce(sum(invest), 0),
      'transfer_in', coalesce(sum(transfer_in), 0), 'transfer_out', coalesce(sum(transfer_out), 0),
      'loan_in', coalesce(sum(loan_in), 0), 'loan_out', coalesce(sum(loan_out), 0),
      'closing', coalesce(sum(opening + income + transfer_in + loan_in - expense - invest - transfer_out - loan_out), 0))
  into v_accounts, v_totals
  from figs;

  v_income  := (v_totals ->> 'income')::numeric;
  v_expense := (v_totals ->> 'expense')::numeric;
  v_invest  := (v_totals ->> 'invest')::numeric;

  select coalesce(jsonb_agg(jsonb_build_object('name', name, 'amount', amount) order by amount desc), '[]')
  into v_cats
  from (
    select coalesce(c.name, 'Other') as name, sum(t.amount) as amount
    from public.transactions t
    left join public.categories c on c.id = t.category_id
    where t.household_id = p_household and t.type = 'expense' and t.date >= m0 and t.date < m1
    group by coalesce(c.name, 'Other')
  ) x;

  select coalesce(sum(s.realized_pl), 0) into v_realized
  from public.sales s
  where s.household_id = p_household and s.date >= m0 and s.date < m1;

  select jsonb_build_object(
    'entries',       count(*),
    'uncategorised', count(*) filter (where t.category_id is null and t.type not like 'transfer%' and t.type not like 'loan%'),
    'unassigned',    count(*) filter (where t.account_id is null))
  into v_check
  from public.transactions t
  where t.household_id = p_household and t.date >= m0 and t.date < m1;

  return jsonb_build_object(
    'month', m0,
    'accounts', v_accounts,
    'totals', v_totals,
    'savings_rate', case when v_income > 0 then round((v_income - v_expense - v_invest) / v_income * 100, 1) end,
    'realized_pl', v_realized,
    'by_category', v_cats,
    'checklist', v_check
  );
end;
$$;

-- period_statement and close_period call private.period_figures, which the plans
-- migration defined as period_figures_base + plans. Wrap it again to add loans.
alter function private.period_figures(uuid, date) rename to period_figures_plans;

create function private.period_figures(p_household uuid, p_month date)
returns jsonb
language sql stable security definer set search_path = ''
as $$
  with l as (select private.loan_figures(p_household, p_month) as loans)
  select private.period_figures_plans(p_household, p_month)
    || jsonb_build_object(
         'loans', l.loans,
         'loans_outstanding', (select coalesce(sum((x ->> 'outstanding')::numeric), 0) from jsonb_array_elements(l.loans) x))
  from l;
$$;

-- Closing snapshots: store the loan columns and the Loans section (FR-CLS-16).
alter table public.ledger_closings
  add column loan_in  numeric(18, 2) not null default 0,
  add column loan_out numeric(18, 2) not null default 0,
  add column loans    jsonb not null default '[]',
  add column loans_outstanding numeric(18, 2) not null default 0;
alter table public.ledger_closing_accounts
  add column loan_in  numeric(18, 2) not null default 0,
  add column loan_out numeric(18, 2) not null default 0;

create function private.closing_loans()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_fig jsonb := private.period_figures_base(new.household_id, new.month);
begin
  new.loan_in  := (v_fig #>> '{totals,loan_in}')::numeric;
  new.loan_out := (v_fig #>> '{totals,loan_out}')::numeric;
  new.loans    := private.loan_figures(new.household_id, new.month);
  new.loans_outstanding := (select coalesce(sum((x ->> 'outstanding')::numeric), 0) from jsonb_array_elements(new.loans) x);
  return new;
end;
$$;

create trigger ledger_closings_loans
  before insert on public.ledger_closings
  for each row execute function private.closing_loans();

create function private.closing_account_loans()
returns trigger
language plpgsql security definer set search_path = ''
as $$
declare
  v_month date;
begin
  select month into v_month from public.ledger_closings where id = new.closing_id;
  select coalesce(sum(t.amount) filter (where t.type = 'loan-in'), 0),
         coalesce(sum(t.amount) filter (where t.type = 'loan-out'), 0)
  into new.loan_in, new.loan_out
  from public.transactions t
  where t.household_id = new.household_id and t.account_id is not distinct from new.account_id
    and t.date >= v_month and t.date < (v_month + interval '1 month')::date;
  return new;
end;
$$;

create trigger ledger_closing_accounts_loans
  before insert on public.ledger_closing_accounts
  for each row execute function private.closing_account_loans();

-- ---------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------
create function private.loan_category(p_household uuid)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_cat uuid;
begin
  select id into v_cat from public.categories where household_id = p_household and lower(name) = 'loan';
  if v_cat is null then
    insert into public.categories (household_id, name) values (p_household, 'Loan') returning id into v_cat;
  end if;
  return v_cat;
end;
$$;

create function private.loan_desc(p_prefix text, p_borrower uuid, p_note text)
returns text
language sql stable security definer set search_path = ''
as $$
  select p_prefix || coalesce(' ' || (select split_part(email, '@', 1) from auth.users where id = p_borrower), '')
    || case when coalesce(trim(p_note), '') <> '' then ' - ' || trim(p_note) else '' end;
$$;

-- Lend money out of an account to a household member.
create function public.add_loan(
  p_household uuid,
  p_account   uuid,
  p_amount    numeric,
  p_borrower  uuid,
  p_date      date default null,
  p_due_date  date default null,
  p_note      text default '',
  p_source    text default 'web'
)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  v_date date := coalesce(p_date, (now() at time zone 'Asia/Jakarta')::date);
  v_id   uuid;
begin
  if not private.is_member(p_household) then raise exception 'Not a member of this household'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Amount must be positive'; end if;
  if not exists (select 1 from public.accounts where id = p_account and household_id = p_household) then
    raise exception 'Account not found in this household';
  end if;
  if not exists (select 1 from public.members where household_id = p_household and user_id = p_borrower) then
    raise exception 'The borrower must be a member of this household';
  end if;
  if p_due_date is not null and p_due_date < v_date then
    raise exception 'The due date cannot be before the loan date';
  end if;

  perform set_config('ft.loan', '1', true);
  insert into public.loans (household_id, borrower_id, amount, date, due_date, note, account_id)
  values (p_household, p_borrower, p_amount, v_date, p_due_date, coalesce(trim(p_note), ''), p_account)
  returning id into v_id;

  insert into public.transactions
    (household_id, date, type, category_id, description, amount, source, account_id, loan_id)
  values
    (p_household, v_date, 'loan-out', private.loan_category(p_household),
     private.loan_desc('Loan to', p_borrower, p_note), p_amount, p_source, p_account, v_id);
  perform set_config('ft.loan', '', true);
  return v_id;
end;
$$;

-- A repayment: money comes back into an account.
create function public.add_loan_payment(
  p_loan    uuid,
  p_account uuid,
  p_amount  numeric,
  p_date    date default null,
  p_note    text default '',
  p_source  text default 'web'
)
returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  l       public.loans;
  v_date  date := coalesce(p_date, (now() at time zone 'Asia/Jakarta')::date);
  v_left  numeric;
  v_id    uuid;
begin
  select * into l from public.loans where id = p_loan for update;
  if l.id is null or not private.is_member(l.household_id) then raise exception 'Loan not found'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Amount must be positive'; end if;
  if not exists (select 1 from public.accounts where id = p_account and household_id = l.household_id) then
    raise exception 'Account not found in this household';
  end if;
  if v_date < l.date then raise exception 'A repayment cannot be dated before the loan (%)', to_char(l.date, 'DD Mon YYYY'); end if;
  v_left := l.amount - private.loan_repaid(l.id);
  if p_amount > v_left then
    raise exception 'Only % is still owed on this loan', v_left;
  end if;

  perform set_config('ft.loan', '1', true);
  insert into public.transactions
    (household_id, date, type, category_id, description, amount, source, account_id, loan_id)
  values
    (l.household_id, v_date, 'loan-in', private.loan_category(l.household_id),
     private.loan_desc('Loan repayment from', l.borrower_id, p_note), p_amount, p_source, p_account, l.id)
  returning id into v_id;
  perform private.refresh_loan(l.id);
  perform set_config('ft.loan', '', true);
  return v_id;
end;
$$;

-- Remove a repayment (open months only; the closed-month trigger refuses the rest).
create function public.delete_loan_payment(p_txn uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  t public.transactions;
begin
  select * into t from public.transactions where id = p_txn and type = 'loan-in' for update;
  if t.id is null or not private.is_member(t.household_id) then raise exception 'Payment not found'; end if;
  perform 1 from public.loans where id = t.loan_id for update;
  perform set_config('ft.loan', '1', true);
  delete from public.transactions where id = p_txn;
  perform private.refresh_loan(t.loan_id);
  perform set_config('ft.loan', '', true);
end;
$$;

-- Edit a loan. p_fields keys: account, amount, date, borrower, due_date, note.
-- Money fields (account, amount, date) change only while there are no repayments.
create function public.update_loan(p_loan uuid, p_fields jsonb)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  l       public.loans;
  v_acc   uuid;
  v_amt   numeric;
  v_date  date;
  v_bor   uuid;
  v_due   date;
  v_note  text;
  v_money boolean;
  v_pay   int;
begin
  select * into l from public.loans where id = p_loan for update;
  if l.id is null or not private.is_member(l.household_id) then raise exception 'Loan not found'; end if;

  v_acc  := case when p_fields ? 'account'  then (p_fields ->> 'account')::uuid  else l.account_id end;
  v_amt  := case when p_fields ? 'amount'   then (p_fields ->> 'amount')::numeric else l.amount end;
  v_date := case when p_fields ? 'date'     then (p_fields ->> 'date')::date     else l.date end;
  v_bor  := case when p_fields ? 'borrower' then (p_fields ->> 'borrower')::uuid else l.borrower_id end;
  v_due  := case when p_fields ? 'due_date' then (p_fields ->> 'due_date')::date else l.due_date end;
  v_note := case when p_fields ? 'note'     then coalesce(trim(p_fields ->> 'note'), '') else l.note end;

  v_money := v_acc is distinct from l.account_id or v_amt <> l.amount or v_date <> l.date;
  select count(*) into v_pay from public.transactions where loan_id = l.id and type = 'loan-in';
  if v_money and v_pay > 0 then
    raise exception 'Amount, date and account cannot change once repayments exist. Delete the repayments first.';
  end if;
  if v_amt <= 0 then raise exception 'Amount must be positive'; end if;
  if v_due is not null and v_due < v_date then raise exception 'The due date cannot be before the loan date'; end if;
  if v_bor is distinct from l.borrower_id
     and not exists (select 1 from public.members where household_id = l.household_id and user_id = v_bor) then
    raise exception 'The borrower must be a member of this household';
  end if;
  if v_money and not exists (select 1 from public.accounts where id = v_acc and household_id = l.household_id) then
    raise exception 'Account not found in this household';
  end if;

  if v_money then
    perform set_config('ft.loan', '1', true);
    update public.transactions
    set amount = v_amt, date = v_date, account_id = v_acc,
        description = private.loan_desc('Loan to', v_bor, v_note)
    where loan_id = l.id and type = 'loan-out';
    perform set_config('ft.loan', '', true);
  end if;
  update public.loans
  set account_id = v_acc, amount = v_amt, date = v_date, borrower_id = v_bor, due_date = v_due, note = v_note
  where id = l.id;
  perform private.refresh_loan(l.id);
end;
$$;

-- Delete a loan that has no repayments, together with its loan-out entry.
create function public.delete_loan(p_loan uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  l public.loans;
begin
  select * into l from public.loans where id = p_loan for update;
  if l.id is null or not private.is_member(l.household_id) then raise exception 'Loan not found'; end if;
  if exists (select 1 from public.transactions where loan_id = l.id and type = 'loan-in') then
    raise exception 'This loan has repayments. Delete the repayments first.';
  end if;
  perform set_config('ft.loan', '1', true);
  delete from public.transactions where loan_id = l.id;
  delete from public.loans where id = l.id;
  perform set_config('ft.loan', '', true);
end;
$$;

-- Members with their email, so the app can offer a borrower list. The members
-- table has no names; any member of the household may read this list.
create function public.household_members(p_household uuid)
returns table (user_id uuid, role text, email text)
language plpgsql stable security definer set search_path = ''
as $$
begin
  if not private.is_member(p_household) then raise exception 'Not a member of this household'; end if;
  return query
    select m.user_id, m.role, u.email::text
    from public.members m join auth.users u on u.id = m.user_id
    where m.household_id = p_household
    order by m.role desc, u.email;
end;
$$;

-- ---------------------------------------------------------------
-- Notifications (FR-LON-11)
-- ---------------------------------------------------------------
alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check
  check (kind in ('plan_milestone', 'plan_achieved', 'plan_behind', 'plan_deadline', 'plan_overdue', 'plan_monthly',
                  'month_close', 'loan_due', 'loan_overdue'));
alter table public.notification_prefs drop constraint notification_prefs_kind_check;
alter table public.notification_prefs add constraint notification_prefs_kind_check
  check (kind in ('plan_milestone', 'plan_achieved', 'plan_behind', 'plan_deadline', 'plan_overdue', 'plan_monthly',
                  'month_close', 'loan_due', 'loan_overdue'));

create function private.check_loans(p_household uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
declare
  l       record;
  v_today date := (now() at time zone 'Asia/Jakarta')::date;
  v_left  numeric;
begin
  for l in select * from public.loans where household_id = p_household and status = 'open' and due_date is not null loop
    v_left := l.amount - private.loan_repaid(l.id);
    if l.due_date < v_today then
      perform private.notify(p_household, 'loan_overdue', l.id, 'overdue:' || l.due_date || ':' || to_char(v_today, 'IYYY-IW'),
        'A loan is overdue',
        private.rp(v_left) || ' is still owed. It was due ' || private.long_date(l.due_date) || '.', 'loan:' || l.id);
    elsif l.due_date - v_today <= 7 then
      perform private.notify(p_household, 'loan_due', l.id, '7d:' || l.due_date,
        case when l.due_date = v_today then 'A loan is due today' else 'A loan is due in ' || (l.due_date - v_today) || ' days' end,
        private.rp(v_left) || ' to pay back by ' || private.long_date(l.due_date) || '.', 'loan:' || l.id);
    end if;
  end loop;
end;
$$;

-- check_household (replaced by 20261121) keeps its body; loan checks run after it.
alter function private.check_household(uuid) rename to check_household_plans;

create function private.check_household(p_household uuid)
returns void
language plpgsql security definer set search_path = ''
as $$
begin
  perform private.check_household_plans(p_household);
  perform private.check_loans(p_household);
end;
$$;

